55: export function approveSection(project: Project, sectionId: string, version: number, hash: string): Project {
56:   const next = clone(project);
57:   const section = next.sections.find((item) => item.id === sectionId);
58:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
59:   if (next.currentSectionId !== sectionId) throw new WorkflowConflict("Only the current section can be approved.");
60:   if (section.status !== "DRAFT" || section.version !== version || section.hash !== hash) {
61:     throw new WorkflowConflict("Approval does not match the current draft version and hash.");
62:   }
63:   const dependenciesReady = section.dependencies.every((dependency) =>
64:     next.sections.find((item) => item.id === dependency)?.status === "APPROVED",
65:   );
66:   if (!dependenciesReady) throw new WorkflowConflict("Section dependencies are not currently approved.");
