136:   const next = clone(project);
137:   next.witnessDrafts = drafts.map((draft) => ({
138:     id: randomUUID(),
139:     title: draft.title,
140:     content: draft.content,
141:     nativeSessionId: sessionId,
142:   }));
143:   rememberSession(next, "witness", sessionId);
144:   rememberTranscript(next, "witness", drafts.map((draft) => draft.title).join(", "));
145:   return projectSchema.parse(refreshNextAction(next));
146: }
