157: export function compileApprovedPlan(project: Project): string {
158:   const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
159:   if (unresolved.length) throw new WorkflowConflict(`Plan has ${unresolved.length} unresolved section(s).`);
160:   return project.sections
161:     .toSorted((left, right) => left.order - right.order)
162:     .map((section) => `## ${section.title}\n\n${section.content}`)
163:     .join("\n\n");
164: }

