1: import { payloadHash, type Project } from "./model.ts";
2: import { AtomicProjectStore, RevisionConflict } from "../store/atomic-project-store.ts";
3: 
4: export interface ActionResult {
5:   project: Project;
6:   duplicate: boolean;
7: }
8: 
9: export class WorkflowService {
10:   constructor(private readonly store: AtomicProjectStore) {}
11: 
12:   async get(): Promise<Project> {
13:     return (await this.store.load()).state;
14:   }
15: 
16:   async execute(
17:     actionId: string,
18:     payload: unknown,
19:     expectedRevision: number,
20:     mutation: (project: Project) => Project,
21:   ): Promise<ActionResult> {
22:     const loaded = await this.store.load();
23:     const hash = payloadHash(payload);
24:     const existing = loaded.state.actions.find((action) => action.id === actionId);
25:     if (existing) {
26:       if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
27:       return { project: loaded.state, duplicate: true };
28:     }
29:     if (loaded.state.revision !== expectedRevision) {
30:       throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
31:     }
32:     const next = mutation(loaded.state);
33:     next.actions.push({ id: actionId, payloadHash: hash, resultRevision: expectedRevision + 1 });
34:     return { project: await this.store.save(expectedRevision, next), duplicate: false };
35:   }
36: }

