447: function engineSummary(project: Project, status: ReturnType<ConnectionService["status"]>) {
448:   const model = project.engine.model
449:     ? `${project.engine.model.providerID}/${project.engine.model.id}${project.engine.model.variant ? `#${project.engine.model.variant}` : ""}`
450:     : null;
451:   const modelAvailable = Boolean(status.discovery?.models.some((candidate) =>
452:     candidate.providerID === project.engine.model?.providerID
453:     && candidate.id === project.engine.model?.id
454:     && candidate.availability === "available"
455:     && (project.engine.model?.variant ? candidate.variants.includes(project.engine.model.variant) : true)));
456:   const diagnostic = status.diagnostics.find((item) => item.severity === "error")
457:     ?? status.diagnostics.find((item) => item.severity === "warning");
458:   return engineStatusSchema.parse({
459:     available: Boolean(status.discovery) && status.state !== "incompatible_version" && status.state !== "authentication_required" && status.state !== "unavailable",
460:     state: status.state,
461:     serverVersion: status.serverVersion,
462:     model,
463:     modelAvailable,
464:     limitation: diagnostic?.message ?? null,
465:   });
466: }
