450:     : null;
451:   const modelAvailable = Boolean(status.discovery?.models.some((candidate) =>
452:     candidate.providerID === project.engine.model?.providerID
453:     && candidate.id === project.engine.model?.id
454:     && candidate.availability === "available"
455:     && (project.engine.model?.variant ? candidate.variants.includes(project.engine.model.variant) : true)));
456:   const diagnostic = status.diagnostics.find((item) => item.severity === "error")
457:     ?? status.diagnostics.find((item) => item.severity === "warning");
458:   return engineStatusSchema.parse({
