59: export class ExperienceService {
60:   private readonly runs: MakerRunCoordinator;
61: 
62:   constructor(
63:     private readonly workflow: WorkflowService,
64:     private readonly store: AtomicProjectStore,
65:     private readonly guide: SpiritGuide,
66:     private readonly options: {
67:       safeDirectory: string;
68:       demoWorkspace: string;
69:       promptRoot?: string;
70:       engine: EngineSelectionService;
71:     },
72:   ) {
73:     this.runs = new MakerRunCoordinator({
74:       workflow,
75:       guide,
76:       demoWorkspace: options.demoWorkspace,
77:     });
78:   }
