80:   async sendMessage(actionId: string, expectedRevision: number, intent: "clarify" | "draft" | "question" | "witness", text: string) {
81:     const payload = { intent, text };
82:     const claimed = await this.claim(actionId, payload, expectedRevision);
83:     if (claimed.duplicate) return { project: claimed.project, duplicate: true };
84:     const project = claimed.project;
85:     try {
86:       if (intent === "clarify") return await this.clarify(actionId, payload, expectedRevision, project, text);
87:       if (intent === "draft") return await this.draft(actionId, payload, expectedRevision, project, text);
88:       if (intent === "question") return await this.question(actionId, payload, expectedRevision, project, text);
89:       return await this.witness(actionId, payload, expectedRevision, project, text);
90:     } catch (error) {
91:       if (error instanceof ExperienceFailure || error instanceof WorkflowConflict || error instanceof RevisionConflict) throw error;
92:       return this.recordUncertain(actionId, payload, expectedRevision, intent, error);
93:     }
94:   }
95: 
96:   async approve(actionId: string, expectedRevision: number, kind: "product" | "maker-scope", statement?: string) {
97:     const payload = { kind, statement: statement ?? null };
98:     return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
99:       if (kind === "product") return approveProduct(project);
100:       return grantMakerScope(project, statement ?? "");
101:     });
102:   }
103: 
104:   async runMaker(actionId: string, expectedRevision: number) {
105:     const payload = { intent: "maker" };
106:     const claimed = await this.claim(actionId, payload, expectedRevision);
107:     if (claimed.duplicate) return { project: claimed.project, duplicate: true, accepted: false };
108:     const project = claimed.project;
109:     if (project.makerScope.status !== "GRANTED" || !project.makerScope.statement) {
110:       throw new ExperienceFailure("Grant a separate Maker scope before a native run.", "MAKER_SCOPE_REQUIRED", 409, false);
111:     }
112:     const makerScope = project.makerScope.statement;
113:     const context = await this.modelContext(project);
114:     const startedAt = new Date().toISOString();
115:     const queued = await this.workflow.execute(actionId, payload, expectedRevision, (current) => {
116:       const next = structuredClone(current);
117:       next.engine = {
118:         model: context.model,
119:         source: context.source === "selected"
120:           ? current.engine.source
121:           : context.source === "legacy"
122:             ? "migrated-legacy"
123:             : "auto-discovery",
124:         updatedAt: startedAt,
125:         legacyModel: current.engine.legacyModel,
126:       };
127:       next.operations.push({
128:         id: randomUUID(),
129:         kind: "maker",
130:         payloadHash: payloadHash(payload),
131:         nativeSessionId: null,
132:         nativeMessageId: null,
133:         status: "QUEUED",
134:         result: `Queued for OpenCode with ${context.model.providerID}/${context.model.id}${context.model.variant ? `#${context.model.variant}` : ""}.`,
135:         model: context.model,
136:         agent: context.roleAgents.maker,
137:         startedAt,
138:         finishedAt: null,
139:       });
140:       rememberTranscript(next, "user", `Queued a Maker run with ${context.model.providerID}/${context.model.id}${context.model.variant ? `#${context.model.variant}` : ""}.`);
141:       return refreshNextAction(next);
142:     });
143:     const operation = queued.project.operations.at(-1);
144:     if (!operation) throw new ExperienceFailure("The Maker run was not recorded.", "RUN_NOT_RECORDED", 500, true);
145:     try {
146:       const prompt = await this.instructions("maker", queued.project, makerScope);
147:       this.runs.start({
148:         operationId: operation.id,
149:         projectId: queued.project.id,
150:         actionId,
151:         payload,
152:         sessionId: sessionFor(queued.project, "maker"),
153:         prompt,
154:         workspace: this.options.demoWorkspace,
155:         model: context.model,
156:         agent: context.roleAgents.maker,
157:       });
158:     } catch (error) {
159:       await this.runs.markFailed(operation.id, error, context.model, context.roleAgents.maker);
160:       throw error instanceof ExperienceFailure
161:         ? error
162:         : new ExperienceFailure(error instanceof Error ? error.message : "The Maker run could not start.", "RUN_START_FAILED", 500, true, operation.id);
163:     }
164:     return { project: queued.project, duplicate: false, accepted: true, operation };
165:   }
166: 
167:   async cancel(actionId: string, expectedRevision: number, operationId: string) {
168:     void expectedRevision;
169:     const active = this.runs.active(operationId);
170:     if (!active) {
171:       const project = (await this.store.load()).state;
172:       const operation = project.operations.find((item) => item.id === operationId);
173:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
174:       if (["SUCCEEDED", "FAILED", "CANCELLED", "UNKNOWN"].includes(operation.status)) {
175:         throw new WorkflowConflict("A finished or unknown operation cannot be cancelled. Reconcile an unknown operation instead.");
176:       }
177:       throw new ExperienceFailure("The in-process runner is no longer present. Reconcile the native session before taking another action.", "RUN_NOT_ACTIVE", 409, false, operationId);
178:     }
179:     this.runs.markCancelled(operationId);
180:     let interrupted = false;
181:     if (active.sessionId) {
182:       try {
183:         interrupted = await this.guide.interrupt(active.sessionId);
184:       } catch {
185:         interrupted = false;
186:       }
187:     }
188:     // Cancellation is corrective: the background completion may advance the
189:     // project revision between the browser's snapshot and this request. Apply
190:     // against the latest revision while retaining action-ID idempotency.
191:     return this.workflow.executeLatest(actionId, { operationId, intent: "cancel" }, (project) => {
192:       const next = structuredClone(project);
193:       const operation = next.operations.find((item) => item.id === operationId);
194:       if (!operation) throw new WorkflowConflict("That operation is not in this project.");
195:       if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) {
196:         if (operation.status === "CANCELLED") return next;
197:         throw new WorkflowConflict("A finished operation cannot be cancelled.");
198:       }
199:       operation.status = "CANCELLED";
200:       operation.finishedAt = new Date().toISOString();
201:       operation.result = interrupted
202:         ? "Interrupted the native OpenCode session; the run was cancelled."
203:         : "Cancellation recorded. The native session was already idle or did not report an active request.";
204:       rememberTranscript(next, "system", operation.result);
205:       return refreshNextAction(next);
206:     });
207:   }
208: 
209:   async reconcile(actionId: string, expectedRevision: number, operationId: string) {
210:     const payload = { operationId, intent: "reconcile" };
211:     const claimed = await this.claim(actionId, payload, expectedRevision);
212:     if (claimed.duplicate) return { project: claimed.project, duplicate: true };
213:     const operation = claimed.project.operations.find((item) => item.id === operationId);
214:     if (!operation?.nativeSessionId) {
215:       throw new ExperienceFailure("This operation has no native session to reconcile.", "NOTHING_TO_RECONCILE", 409, false);
216:     }
217:     const role = operation.kind === "maker" ? "maker" : operation.kind === "witness" ? "witness" : "architect";
218:     const observed = await this.guide.inspect(operation.nativeSessionId, {
219:       conversationId: claimed.project.id,
220:       role,
221:     });
222:     return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
223:       const next = structuredClone(project);
224:       const current = next.operations.find((item) => item.id === operationId);
225:       if (!current) throw new WorkflowConflict("That operation is not in this project.");
226:       if (observed === "running") {
227:         current.status = "RUNNING";
228:         current.result = "Native session is still running. It was not started again.";
229:       } else if (observed === "succeeded") {
230:         current.status = "SUCCEEDED";
231:         current.finishedAt ??= new Date().toISOString();
232:         current.result = "Reconciled from the native session outcome.";
233:       } else if (observed === "failed") {
234:         current.status = "FAILED";
235:         current.finishedAt ??= new Date().toISOString();
236:         current.result = "Reconciled from a failed or interrupted native session.";
237:       } else {
238:         current.status = "UNKNOWN";
239:         current.result = "Native outcome is still unknown. This action was not repeated.";
240:       }
241:       return refreshNextAction(next);
242:     });
243:   }
