249:   async exportApproved() {
250:     const project = await this.workflow.get();
251:     const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
252:     const plan = unresolved.length
253:       ? null
254:       : project.sections
255:         .toSorted((left, right) => left.order - right.order)
256:         .map((section) => `## ${section.title}\n\n${section.content}`)
257:         .join("\n\n");
258:     return {
259:       plan,
260:       unresolved: unresolved.map((section) => section.id),
261:       drafts: project.witnessDrafts.map((draft) => ({ title: draft.title, content: draft.content })),
262:       engine: project.engine,
263:       limitation: "Witness drafts are in-app review notes. They are not a submitted article, video, or entry.",
264:     };
265:   }
