267:   private async clarify(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
268:     return traceAgentOperation("oracle", project.id, async () => {
269:       if (project.product.status === "APPROVED") {
270:         throw new ExperienceFailure("The product proposal is already approved.", "PRODUCT_ALREADY_APPROVED", 409, false);
271:       }
272:       const context = await this.modelContext(project);
273:       const spoken = await this.guide.speak({
274:         role: "oracle",
275:         conversationId: project.id,
276:         sessionId: sessionFor(project, "oracle"),
277:         prompt: await this.instructions("oracle", project, text),
278:         workspace: this.options.safeDirectory,
279:         model: context.model,
280:         agent: context.roleAgents.oracle,
281:       });
282:       const reply = oracleReplySchema.parse(extractJsonObject(spoken.text));
283:       return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
284:         const seeded = structuredClone(current);
285:         rememberTranscript(seeded, "user", text);
286:         const next = recordOracleProposal(seeded, { ...reply, sessionId: spoken.sessionId });
287:         next.operations.push(operation("guide", payload, spoken, "Oracle proposal stored. It is not approved.", context.model));
288:         return refreshNextAction(next);
289:       });
290:     });
291:   }
