293:   private async draft(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
294:     return traceAgentOperation("architect", project.id, async () => {
295:       if (project.product.status !== "APPROVED" || !project.currentSectionId) {
296:         throw new ExperienceFailure("Drafting waits for an approved product and an active section.", "SECTION_NOT_READY", 409, false);
297:       }
298:       const sectionId = project.currentSectionId;
299:       const context = await this.modelContext(project);
300:       const spoken = await this.guide.speak({
301:         role: "architect",
302:         conversationId: project.id,
303:         sessionId: sessionFor(project, "architect"),
304:         prompt: await this.instructions("architect", project, text),
305:         workspace: this.options.safeDirectory,
306:         model: context.model,
307:         agent: context.roleAgents.architect,
308:       });
309:       let reply;
310:       try {
311:         reply = sectionReplySchema.parse(extractJsonObject(spoken.text));
312:       } catch {
313:         const prose = spoken.text.trim();
314:         if (prose.length < 80) {
315:           return this.recordFailure(actionId, payload, expectedRevision, "architect", spoken.sessionId, `The Architect reply was malformed, so the section was left unchanged. Reply began: ${prose.slice(0, 240)}`);
316:         }
317:         reply = {
318:           content: prose.slice(0, 12_000),
319:           recommendation: "The Architect returned prose. Review the draft before approval.",
320:           tradeoff: "Separate recommendation and tradeoff fields were not returned.",
321:         };
322:       }
323:       const content = formatSectionDraft(reply);
324:       return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
325:         const next = reviseSection(current, sectionId, content);
326:         rememberSession(next, "architect", spoken.sessionId);
327:         rememberTranscript(next, "user", text);
328:         rememberTranscript(next, "architect", content);
329:         next.operations.push(operation("guide", payload, spoken, "Draft stored as the current section version.", context.model));
330:         return refreshNextAction(next);
331:       });
332:     });
333:   }
