361:       const makerDone = project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED");
362:       if (!makerDone) throw new ExperienceFailure("Witness review waits for a completed Maker run.", "WITNESS_NOT_READY", 409, false);
363:       const context = await this.modelContext(project);
364:       const spoken = await this.guide.speak({
365:         role: "witness",
366:         conversationId: project.id,
367:         sessionId: null,
368:         prompt: await this.instructions("witness", project, text),
369:         workspace: this.options.safeDirectory,
370:         model: context.model,
371:         agent: context.roleAgents.witness,
372:       });
373:       let reply;
374:       try {
375:         reply = witnessReplySchema.parse(extractJsonObject(spoken.text));
376:       } catch {
377:         const prose = spoken.text.trim();
378:         if (prose.length < 80) {
379:           return this.recordFailure(actionId, payload, expectedRevision, "witness", spoken.sessionId, `The Witness reply was malformed, so no draft was stored. Reply began: ${prose.slice(0, 240)}`);
380:         }
381:         reply = {
382:           findings: prose.slice(0, 8_000),
383:           limitations: "The Witness returned prose rather than separate fields.",
384:           draftNotes: "These notes are an in-app review. They are not a submitted article or video.",
385:         };
