399:   private async instructions(role: "oracle" | "architect" | "maker" | "witness", project: Project, text: string): Promise<string> {
400:     const procedure = await loadStagePrompt(role === "maker" ? "maker" : stagePrompt[role], this.options.promptRoot);
401:     const section = project.sections.find((item) => item.id === project.currentSectionId);
402:     const shape = role === "oracle"
403:       ? '{"clarification":"...","proposal":"...","openQuestions":["..."]}'
404:       : role === "architect"
405:         ? '{"content":"...","recommendation":"...","tradeoff":"..."}'
406:         : role === "witness"
407:           ? '{"findings":"...","limitations":"...","draftNotes":"..."}'
408:           : "a code change, not JSON";
409:     return [
410:       procedure,
411:       "",
412:       "Current workshop state:",
413:       `stage ${project.stage}; product ${project.product.status}; next ${project.nextAction}`,
414:       `selected model ${project.engine.model ? `${project.engine.model.providerID}/${project.engine.model.id}${project.engine.model.variant ? `#${project.engine.model.variant}` : ""}` : "not chosen by the user"}`,
415:       section ? `active section ${section.order}. ${section.title}; version ${section.version}; status ${section.status}` : "no active section",
416:       project.product.proposal ? `approved-or-proposed product:\n${project.product.proposal}` : "no product proposal yet",
417:       project.evidence.length ? `observed checks:\n${project.evidence.map((item) => `${item.checkId} ${item.result}. ${item.limitation ?? ""}`).join("\n")}` : "no observed checks yet",
418:       project.operations.some((item) => item.kind === "maker")
419:         ? `maker results:\n${project.operations.filter((item) => item.kind === "maker").map((item) => item.result ?? item.status).join("\n")}`
420:         : "no maker result yet",
421:       "The spirit session directory is empty on purpose. Do not treat it as the demo workspace, and do not claim files are missing when a maker result or check is listed above.",
422:       "",
423:       "User message:",
424:       text,
425:       "",
426:       role === "maker"
427:         ? "The session directory is an isolated demo workspace. Implement the approved plan and Maker scope there as a dependency-free Node module plus a node:test file. Do not edit the Unfinished Business repository, do not run shell commands, and do not claim a test passed."
428:         : `Reply with one JSON object only, matching ${shape}. Do not approve, advance, or claim the user approved. A question is not approval.`,
429:     ].join("\n");
430:   }
