432:   private async modelContext(project: Project): Promise<{
433:     model: ModelRef;
434:     source: "selected" | "legacy" | "auto-discovery";
435:     roleAgents: Record<"oracle" | "architect" | "maker" | "witness", string | null>;
436:   }> {
437:     let discovery: OpenCodeDiscovery;
438:     try {
439:       discovery = await this.options.engine.discovery({ selected: project.engine.model });
440:     } catch (error) {
441:       throw new ExperienceFailure(
442:         `OpenCode discovery is unavailable: ${error instanceof Error ? error.message : "unknown error"}`,
443:         "OPENCODE_UNAVAILABLE",
444:         503,
445:         true,
446:       );
447:     }
448:     let resolution = project.engine.model
449:       ? await this.options.engine.resolveModel(project.engine.model, discovery)
450:       : null;
451:     if (project.engine.model && !resolution) {
452:       const reported = discovery.models.find((model) =>
453:         model.providerID === project.engine.model?.providerID && model.id === project.engine.model?.id);
454:       throw new ExperienceFailure(
455:         reported
456:           ? `The selected model ${project.engine.model.providerID}/${project.engine.model.id} is not available. Choose another model in the OpenCode panel.`
457:           : `The selected model ${project.engine.model.providerID}/${project.engine.model.id} is no longer reported by OpenCode. Choose another model in the OpenCode panel.`,
458:         "MODEL_UNAVAILABLE",
459:         409,
460:         false,
461:       );
462:     }
463:     if (!resolution) {
464:       // A migrated v1 project may preserve its old model only when OpenCode
465:       // still reports it. Never auto-select an unrelated model or a paid model
466:       // on the user's behalf.
467:       if (project.engine.legacyModel) {
468:         resolution = await this.options.engine.chooseDefaultModel(project.engine.legacyModel);
469:       }
470:       if (!resolution) {
471:         throw new ExperienceFailure(
472:           "Choose a model reported by OpenCode before starting a run.",
473:           "MODEL_SELECTION_REQUIRED",
474:           409,
475:           false,
476:         );
477:       }
478:     }
479:     if (project.engine.model?.variant) {
480:       this.options.engine.validateSelection(discovery, project.engine.model);
481:     }
482:     const roleAgents = Object.fromEntries(
483:       discovery.roles.map((role) => [role.role, role.available ? role.agent : null]),
484:     ) as Record<"oracle" | "architect" | "maker" | "witness", string | null>;
485:     return {
486:       model: { providerID: resolution.model.providerID, id: resolution.model.id, variant: project.engine.model?.variant ?? null },
487:       source: resolution.source,
488:       roleAgents,
489:     };
490:   }
