492:   private async claim(actionId: string, payload: object, expectedRevision: number): Promise<Claimed> {
493:     const loaded = await this.store.load();
494:     const hash = payloadHash(payload);
495:     const existing = loaded.state.actions.find((action) => action.id === actionId);
496:     if (existing) {
497:       if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
498:       return { project: loaded.state, duplicate: true };
499:     }
500:     if (loaded.state.revision !== expectedRevision) {
501:       throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
502:     }
503:     return { project: loaded.state, duplicate: false };
504:   }
