506:   private async recordFailure(
507:     actionId: string,
508:     payload: object,
509:     expectedRevision: number,
510:     role: SpiritRole,
511:     sessionId: string | null,
512:     message: string,
513:   ) {
514:     const saved = await this.workflow.execute(actionId, payload, expectedRevision, (project) => {
515:       const next = structuredClone(project);
516:       const operationId = randomUUID();
517:       next.operations.push({
518:         id: operationId,
519:         kind: role === "witness" ? "witness" : "guide",
520:         payloadHash: payloadHash(payload),
521:         nativeSessionId: sessionId,
522:         nativeMessageId: null,
523:         status: "FAILED",
524:         result: message,
525:         model: project.engine.model,
526:         agent: null,
527:         startedAt: null,
528:         finishedAt: new Date().toISOString(),
529:       });
530:       rememberTranscript(next, "system", message);
531:       return refreshNextAction(next);
532:     });
533:     throw new ExperienceFailure(message, "MALFORMED_RESPONSE", 400, true, saved.project.operations.at(-1)?.id ?? null);
534:   }
