  id: z.string(),
  revision: z.number().int().nonnegative(),
  workspace: z.string(),
  stage: z.enum(["ORACLE", "ARCHITECT", "MAKER", "WITNESS"]),
  currentSectionId: z.string().nullable(),
  sections: z.array(sectionSchema),
  approvals: z.array(approvalSchema),
  actions: z.array(actionSchema),
  operations: z.array(operationSchema),
  evidence: z.array(evidenceSchema),
  nextAction: z.string(),
  product: productSchema.default({ status: "NONE", proposal: null, openQuestions: [] }),
  makerScope: makerScopeSchema.default({ status: "NONE", statement: null }),
  transcript: z.array(transcriptEntrySchema).default([]),
  capabilities: z.array(capabilitySchema).default([]),
  witnessDrafts: z.array(witnessDraftSchema).default([]),
  nativeSessions: z.array(nativeSessionRefSchema).default([]),
});

export const projectV1Schema = projectCoreSchema.extend({
  schemaVersion: z.literal(1),
  operations: z.array(operationCoreSchema),
  evidence: z.array(evidenceCoreSchema),
});

export const projectV2Schema = projectCoreSchema.extend({
  schemaVersion: z.literal(2),
  engine: engineSelectionSchema.default({ model: null, source: "none", updatedAt: null, legacyModel: null }),
});

export const projectSchema = projectCoreSchema.extend({
  schemaVersion: z.literal(3),
  engine: engineSelectionSchema.default({ model: null, source: "none", updatedAt: null, legacyModel: null }),
});

export type Project = z.infer<typeof projectSchema>;
export type PlanSection = z.infer<typeof sectionSchema>;
export type Operation = z.infer<typeof operationSchema>;
export type Capability = z.infer<typeof capabilitySchema>;
export type SpiritRole = "oracle" | "architect" | "maker" | "witness";

/**
 * The eight planning areas in the order a user reviews them. Internal ids stay
 * stable across label changes so approvals, hashes, and dependency edges keep
 * pointing at the same record. `readiness` is the historical id for the
 * budget/tooling area; it moved from last to fifth when the user-facing
 * sections were clarified.
 */
export const sectionDefinitions = [
  ["control", "Vision & Success", []],
  ["architecture", "Architecture", ["control"]],
  ["experience", "User Experience", ["control", "architecture"]],
  ["tools", "OpenCode Setup", ["architecture"]],
  ["readiness", "Tools & Budget", ["control", "architecture", "tools"]],
  ["verification", "Validation", ["control", "architecture", "tools"]],
  ["phases", "Build Roadmap", ["verification"]],
  ["delivery", "Demo & Launch", ["experience", "verification", "phases"]],
] as const;

export type SectionDefinition = (typeof sectionDefinitions)[number];
export type SectionId = SectionDefinition[0];

export const sectionDefinitionById = new Map<string, SectionDefinition>(
  sectionDefinitions.map((definition) => [definition[0], definition]),
);

