type SectionLike = z.infer<typeof sectionSchema>;

function migratedSections(project: { sections: SectionLike[]; approvals: Approval[] }): SectionLike[] {
  const byId = new Map(project.sections.map(s => [s.id, s]));
  const lastApproval = new Map<string,string>();
  for (const approval of project.approvals) {
    const current = lastApproval.get(approval.sectionId);
    if (!current || approval.approvedAt > current) lastApproval.set(...)
  }
  const result = sectionDefinitions.map(([id,title,deps], idx) => {
    const existing = byId.get(id);
    if (!existing) return { id, title, order: idx+1, dependencies: [...deps], content:"", version:0, hash: contentHash(""), status:"NOT_STARTED", updatedAt:null };
    byId.delete(id);
    return { ...existing, title, order: idx+1, dependencies: [...deps], updatedAt: existing.updatedAt ?? lastApproval.get(id) ?? null };
  });
  // Preserve unknown sections after the canonical eight.
  return [...result, ...Array.from(byId.values()).sort((a,b)=>a.order-b.order).map((s,i)=>({...s, order: result.length+i+1}))];
}
```

But `Approval` type from schema. `z.infer<typeof approvalSchema>`. Fine.

Migration v2:
```
const v2 = projectV2Schema.parse(record);
return projectSchema.parse({ ...v2, schemaVersion: 3, sections: migratedSections(v2) });
```
Need `refreshNextAction`? Migration shouldn't change stage/nextAction? New titles mean `nextAction` may mention old title (e.g., "Review Control, product..."). We should recompute nextAction, but `refreshNextAction` mutates and may change stage based on sections/order. That's desired. But it would also change `currentSectionId` based on new order, and stage. Good. Do we want migration to alter active stage? IA changed, but current section should recalc. Yes. However, "viewing/selected tab must not change active workflow state" not migration. Fine. Use `refreshNextAction` on the parsed project then parse again? `refreshNextAction` mutates and returns Project. We can call after parse. But for an approved-v2 project with product approved and all sections approved, stage derived as WITNESS/MAKER. Fine. For old v2 where `readiness` approved last, all approved. Fine.

Potential issue: `projectV2Schema.parse` uses new sectionSchema with updatedAt default null. Good. `projectV1Schema` too.

`createProject`: schemaVersion 3, sections updatedAt null. Add `updatedAt: null` in map. `sectionDefinitions.map` type inference includes title/deps. Fine.

