/**
 * Applies the current user-facing labels, order, and dependency edges without
 * touching the records that make an approval valid. Section ids, content,
 * content hashes, versions, statuses, and approvals stay exactly as persisted.
 * The historical `readiness` id is retained for the Tools & Budget area.
 */
function withCurrentSectionLabels(project: {
  sections: z.infer<typeof sectionSchema>[];
  approvals: z.infer<typeof approvalSchema>[];
}): z.infer<typeof sectionSchema>[] {
  const byId = new Map(project.sections.map((section) => [section.id, section]));
  const lastApproval = new Map<string, string>();
  for (const approval of project.approvals) {
    const current = lastApproval.get(approval.sectionId);
    if (!current || approval.approvedAt > current) lastApproval.set(approval.sectionId, approval.approvedAt);
  }
  const labelled = sectionDefinitions.map(([id, title, dependencies], index) => {
    const existing = byId.get(id);
    byId.delete(id);
    if (!existing) {
      return {
        id,
        title,
        order: index + 1,
        dependencies: [...dependencies],
        content: "",
        version: 0,
        hash: contentHash(""),
        status: "NOT_STARTED" as const,
        updatedAt: null,
      };
    }
    return {
      ...existing,
      title,
      order: index + 1,
      dependencies: [...dependencies],
      updatedAt: existing.updatedAt ?? lastApproval.get(id) ?? null,
    };
  });
  const extras = [...byId.values()]
    .toSorted((left, right) => left.order - right.order)
    .map((section, index) => ({ ...section, order: labelled.length + index + 1 }));
  return [...labelled, ...extras];
}

/**
 * Reads a persisted project from any supported schema generation.
 *
 * V1 documents were written when the application hard-coded the free DeepSeek
 * model. They have no engine selection. V2 documents still use the original
 * technical section labels. Migration records the legacy model identity and
 * applies the current labels while preserving every approval and content hash.
 */
export function migrateProject(raw: unknown): Project {
  const record = raw as Record<string, unknown> | null;
  if (!record || typeof record !== "object") throw new Error("Project data is not an object.");
  if (record.schemaVersion === 3) return projectSchema.parse(record);
  if (record.schemaVersion === 2) {
    const current = projectV2Schema.parse(record);
    return projectSchema.parse(refreshNextAction({
      ...current,
      schemaVersion: 3,
      sections: withCurrentSectionLabels(current),
    }));
  }
  if (record.schemaVersion !== 1) {
    throw new Error(`Unsupported project schema version: ${String(record.schemaVersion)}`);
  }
  const legacy = projectV1Schema.parse(record);
  const migrated = projectV2Schema.parse({
    ...legacy,
    schemaVersion: 2,
    engine: {
      model: null,
      source: "migrated-legacy",
      updatedAt: null,
      legacyModel: LEGACY_FIXED_MODEL_KEY,
    },
    operations: legacy.operations.map((operation) => ({
      ...operation,
      model: null,
      agent: null,
      startedAt: null,
      finishedAt: null,
    })),
    evidence: legacy.evidence.map((evidence) => ({ ...evidence, model: null })),
  });
  return projectSchema.parse(refreshNextAction({
    ...migrated,
    schemaVersion: 3,
    sections: withCurrentSectionLabels(migrated),
  }));
}

export function createProject(workspace: string): Project {
  const sections = sectionDefinitions.map(([id, title, dependencies], index) => ({
    id,
    title,
    order: index + 1,
    dependencies: [...dependencies],
    content: "",
    version: 0,
    hash: contentHash(""),
    status: "NOT_STARTED" as const,
    updatedAt: null,
