input.newString:
export function reviseSection(project: Project, sectionId: string, content: string): Project {
  const next = clone(project);
  const section = next.sections.find((item) => item.id === sectionId);
  if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
  if (next.product.status !== "APPROVED") {
    throw new WorkflowConflict("Sections can only be revised after the Oracle product is approved.");
  }
  const wasApproved = section.status === "APPROVED"
    || next.approvals.some((approval) => approval.sectionId === sectionId);
  if (next.currentSectionId !== sectionId && !wasApproved) {
    throw new WorkflowConflict("Only the current section or a previously approved section can be revised.");
  }
  const hash = contentHash(content);
  if (section.hash === hash && section.version > 0) return next;

  section.content = content;
  section.hash = hash;
  section.version += 1;
  section.status = "DRAFT";
  section.updatedAt = new Date().toISOString();

