const sectionPurpose: Record<string, string> = {
  control: "Define the product promise, audience, scope, and measurable success criteria.",
  architecture: "Record the system shape, contracts, data, and trust boundaries.",
  experience: "Describe the user journey, screen states, accessibility, and responsive behavior.",
  tools: "Choose the OpenCode model, agents, permissions, sessions, and connection.",
