export function parseStageView(raw: string | null | undefined): StageId | null {
  if (typeof raw !== "string") return null;
  const value = raw.trim().toUpperCase();
  return (stageIds as readonly string[]).includes(value) ? value as StageId : null;
}

export function resolveSelectedStage(raw: string | null | undefined, activeStage: StageId): StageId {
  return parseStageView(raw) ?? activeStage;
}

export function viewHref(stage: StageId, search = ""): string {
  const parameters = new URLSearchParams(search.startsWith("?") ? search.slice(1) : search);
  parameters.set("view", stage.toLowerCase());
  return `?${parameters.toString()}`;
}

export function stageIndex(stage: StageId): number {
  return stageIds.indexOf(stage);
}

export function stageRelationship(activeStage: StageId, selectedStage: StageId): StageRelationship {
  const active = stageIndex(activeStage);
  const selected = stageIndex(selectedStage);
  if (selected < active) return "completed";
  if (selected > active) return "future";
  return "active";
}

export function stageReached(activeStage: StageId, stage: StageId): boolean {
  return stageIndex(stage) <= stageIndex(activeStage);
}

export function stageRelationshipLabel(relationship: StageRelationship): string {
  if (relationship === "completed") return "Completed";
  if (relationship === "future") return "Future";
  return "Active";
}

export function stageAriaLabel(stage: StageId, relationship: StageRelationship): string {
  return `${stageMeta[stage].label}, ${stageRelationshipLabel(relationship).toLowerCase()} stage`;
}

export function activeStageBadge(activeStage: StageId): string {
  return `Active stage: ${stageMeta[activeStage].label}`;
}

export function progressLabel(project: WorkshopProject): string {
  const approved = project.sections.filter((section) => section.status === "APPROVED").length;
  const reached = stageIndex(project.stage) + 1;
  return `${stageMeta[project.stage].label} active · ${approved} of ${project.sections.length} sections approved · ${reached} of ${stageIds.length} stages reached`;
}

export function latestApproval(project: WorkshopProject, sectionId: string): SectionApprovalView | null {
  const approval = project.approvals
    .filter((item) => item.sectionId === sectionId)
    .toSorted((left, right) => right.approvedAt.localeCompare(left.approvedAt))[0];
  return approval
    ? {
      id: approval.id,
      version: approval.version,
      approvedAt: approval.approvedAt,
      staleReason: approval.staleReason,
    }
    : null;
}

export function summaryOf(content: string, fallback: string): string {
  const plain = content
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/[#>*_`-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!plain) return fallback;
  return plain.length > 180 ? `${plain.slice(0, 177).trimEnd()}…` : plain;
}

export function sectionState(
  project: WorkshopProject,
  section: WorkshopProject["sections"][number],
  dependenciesMet: boolean,
): SectionState {
  if (section.status === "STALE") return "stale";
  if (section.status === "APPROVED") return "approved";
  if (!dependenciesMet) return "locked";
  if (project.currentSectionId !== section.id) return "blocked";
  if (section.status === "DRAFT") return "draft";
  return "empty";
}

export function sectionStateLabel(state: SectionState): string {
  switch (state) {
    case "approved": return "Ready · approved";
    case "draft": return "Ready · draft";
    case "empty": return "Ready · not started";
    case "stale": return "Stale";
    case "locked": return "Locked";
    case "blocked": return "Blocked";
  }
}

export function buildSectionCards(project: WorkshopProject): SectionCardView[] {
  const byId = new Map(project.sections.map((section) => [section.id, section]));
  return project.sections
    .toSorted((left, right) => left.order - right.order)
    .map((section) => {
      const dependencies = section.dependencies.map((id) => {
        const dependency = byId.get(id);
        return {
          id,
          title: dependency?.title ?? id,
          status: dependency?.status ?? "NOT_STARTED" as const,
          met: dependency?.status === "APPROVED",
        };
      });
      const dependenciesMet = dependencies.every((dependency) => dependency.met);
      const state = sectionState(project, section, dependenciesMet);
      const approval = latestApproval(project, section.id);
      const isCurrent = project.currentSectionId === section.id;
      const action = sectionAction(project, section, state, isCurrent);
      return {
        id: section.id,
        order: section.order,
        title: section.title,
        owner: "Architect",
        status: section.status,
        statusLabel: sectionStatusLabel[section.status],
        state,
        stateLabel: sectionStateLabel(state),
        summary: summaryOf(section.content, sectionPurpose[section.id] ?? "No summary yet."),
        version: section.version,
        content: section.content,
        isCurrent,
        dependencies,
        blockedBy: dependencies.filter((dependency) => !dependency.met).map((dependency) => dependency.id),
        lastUpdate: section.updatedAt ?? approval?.approvedAt ?? null,
        staleReason: section.status === "STALE"
          ? approval?.staleReason ?? "An upstream section changed. Review this section before approval counts."
          : approval?.staleReason ?? null,
        approval,
        approvalLink: `#section-${section.id}-approval`,
        evidenceLink: `#section-${section.id}-evidence`,
        action,
      };
    });
}

function sectionAction(
  project: WorkshopProject,
  section: WorkshopProject["sections"][number],
  state: SectionState,
  isCurrent: boolean,
): SectionCardView["action"] {
  if (state === "locked") {
    return { kind: "locked", label: "Locked by dependencies", href: viewHref("ARCHITECT"), enabled: false };
  }
  if (state === "blocked") {
    return { kind: "blocked", label: "Waiting for earlier sections", href: viewHref("ARCHITECT"), enabled: false };
  }
  if (state === "approved") {
    return { kind: "view", label: "View approval", href: `${viewHref("ARCHITECT")}#section-${section.id}`, enabled: true };
  }
  if (state === "stale") {
    return { kind: "review", label: "Review stale section", href: `${viewHref("ARCHITECT")}#section-${section.id}`, enabled: true };
  }
  if (isCurrent && project.stage === "ARCHITECT") {
    return {
      kind: "edit",
      label: state === "draft" ? "Review & approve" : "Draft section",
      href: `${viewHref("ARCHITECT")}#section-${section.id}`,
      enabled: true,
    };
  }
  return { kind: "review", label: "Review", href: `${viewHref("ARCHITECT")}#section-${section.id}`, enabled: true };
}

export function activeRunOf(project: WorkshopProject): WorkshopProject["operations"][number] | null {
  return project.operations.find((operation) =>
    ["QUEUED", "RUNNING", "WAITING_PERMISSION"].includes(operation.status)) ?? null;
}

export function unknownRunOf(project: WorkshopProject): WorkshopProject["operations"][number] | null {
  return project.operations.find((operation) => operation.status === "UNKNOWN") ?? null;
}

export function latestRunOf(project: WorkshopProject): WorkshopProject["operations"][number] | null {
  return project.operations.at(-1) ?? null;
}

export function runOverview(operation: WorkshopProject["operations"][number] | null): RunOverview | null {
  if (!operation) return null;
  const isActive = ["QUEUED", "RUNNING", "WAITING_PERMISSION"].includes(operation.status);
  return {
    id: operation.id,
    kind: operation.kind,
    status: operation.status,
    model: operation.model
      ? `${operation.model.providerID}/${operation.model.id}${operation.model.variant ? `#${operation.model.variant}` : ""}`
      : null,
    startedAt: operation.startedAt,
    finishedAt: operation.finishedAt,
    result: operation.result,
    isActive,
    canCancel: isActive,
    canReconcile: operation.status === "UNKNOWN" && Boolean(operation.nativeSessionId),
  };
}

export function connectionLabel(state: ConnectionStatus["state"] | "unknown"): string {
  switch (state) {
    case "connected": return "Connected";
    case "degraded": return "Connected with warnings";
    case "checking": return "Checking";
    case "not_configured": return "Not configured";
    case "authentication_required": return "Password required";
    case "incompatible_version": return "Incompatible version";
    case "unavailable": return "Unavailable";
    default: return "Unknown";
  }
}

export function collectBlockers(
  project: WorkshopProject,
  connection: ConnectionStatus | null,
  sections: SectionCardView[],
): BlockerView[] {
  const blockers: BlockerView[] = [];
  const productApproved = project.product.status === "APPROVED";
  const current = project.sections.find((section) => section.id === project.currentSectionId) ?? null;
  const stale = sections.filter((section) => section.state === "stale");
  const selectedModel = findSelectedModel(connection?.discovery ?? null, project.engine.model);
  const makerSucceeded = project.operations.some((operation) =>
    operation.kind === "maker" && operation.status === "SUCCEEDED");
  const activeRun = activeRunOf(project);
  const unknownRun = unknownRunOf(project);

  if (!connection) {
    blockers.push({
      id: "connection-loading",
      label: "OpenCode state not loaded",
      detail: "The workshop is still checking the saved OpenCode connection. Run status is not hidden by navigation.",
      stage: "ALL",
    });
  } else if (connection.state !== "connected" && connection.state !== "degraded") {
    const diagnostic = connection.diagnostics[0];
    blockers.push({
      id: "connection",
      label: `OpenCode ${connectionLabel(connection.state).toLowerCase()}`,
      detail: diagnostic ? `${diagnostic.message} ${diagnostic.repair}` : "Repair the OpenCode connection before a native run.",
      stage: "MAKER",
    });
  } else if (connection.state === "degraded") {
    blockers.push({
      id: "connection-degraded",
      label: "OpenCode has warnings",
      detail: connection.diagnostics[0]?.message ?? "Review the OpenCode panel before relying on a run.",
      stage: "MAKER",
    });
  }

  if (!project.engine.model) {
    blockers.push({
      id: "model",
      label: "No model selected",
      detail: "Choose a model reported by OpenCode before a Maker run. No model is substituted automatically.",
      stage: "MAKER",
    });
  } else if (connection?.discovery && !selectedModel) {
    blockers.push({
      id: "model-unavailable",
      label: "Selected model is unavailable",
      detail: "The saved model is no longer reported by OpenCode. Choose another reported model; the previous choice was not replaced.",
      stage: "MAKER",
    });
  }

  if (!productApproved) {
    blockers.push({
      id: "product",
      label: project.product.status === "PROPOSED" ? "Product approval is pending" : "Product scope not defined",
      detail: project.product.status === "PROPOSED"
        ? "Review the Oracle proposal and approve it, or ask a question. A question is not approval."
        : "Describe the unfinished idea so the Oracle can propose a scope.",
      stage: "ORACLE",
    });
  }

  if (productApproved && current) {
    blockers.push({
      id: `section-${current.id}`,
      label: `${current.title} needs a decision`,
      detail: current.status === "DRAFT"
        ? `Review draft version ${current.version} before approving it.`
        : "Draft or review this section; later sections stay locked until it is approved.",
      stage: "ARCHITECT",
    });
  }

  for (const section of stale) {
    blockers.push({
      id: `stale-${section.id}`,
      label: `${section.title} is stale`,
      detail: section.staleReason ?? "An upstream change invalidated this approval. Review and reapprove it.",
      stage: "ARCHITECT",
    });
  }

  if (productApproved && !current && !stale.length && project.makerScope.status !== "GRANTED") {
    blockers.push({
      id: "maker-scope",
      label: "Maker scope not granted",
      detail: "The plan is approved. Execution still needs a separate, explicit scope statement.",
      stage: "ARCHITECT",
    });
  }

  if (project.makerScope.status === "GRANTED" && !makerSucceeded && !activeRun) {
    blockers.push({
      id: "maker-run",
      label: "Maker has not completed",
      detail: "Run the approved unit in the isolated demo workspace and inspect the saved result.",
      stage: "MAKER",
    });
  }

  if (activeRun) {
    blockers.push({
      id: "run-active",
      label: `${activeRun.kind === "maker" ? "Maker" : "OpenCode"} run ${activeRun.status.toLowerCase()}`,
      detail: "A durable run is in progress. Reloading or changing tabs does not repeat it; inspect or cancel it explicitly.",
      stage: "MAKER",
    });
  }

  if (unknownRun) {
    blockers.push({
      id: `run-unknown-${unknownRun.id}`,
      label: "Native run outcome is unknown",
      detail: "Reconcile the saved OpenCode session before starting another attempt. The run was not repeated.",
      stage: "MAKER",
    });
  }

  if (makerSucceeded && !project.witnessDrafts.length && project.stage === "WITNESS") {
    blockers.push({
      id: "witness",
      label: "Witness review not started",
      detail: "Ask the Witness to review the evidence and prepare findings, limitations, and draft notes.",
      stage: "WITNESS",
    });
  }

  if (!project.evidence.length && project.stage === "WITNESS") {
    blockers.push({
      id: "evidence",
      label: "No evidence recorded",
      detail: "A completed run without observed evidence is a limitation, not a pass. Record or review that limitation.",
      stage: "WITNESS",
    });
  }

  return blockers;
}

export function buildProjectOverview(
  project: WorkshopProject,
  connection: ConnectionStatus | null,
): ProjectOverview {
  const sections = buildSectionCards(project);
  const approved = sections.filter((section) => section.state === "approved").length;
  const stale = sections.filter((section) => section.state === "stale").length;
  const current = project.sections.find((section) => section.id === project.currentSectionId) ?? null;
  const selectedModel = findSelectedModel(connection?.discovery ?? null, project.engine.model);
  const activeRun = activeRunOf(project);
  const latestRun = latestRunOf(project);
  const latestEvidence = project.evidence.at(-1) ?? null;
  const makerSucceeded = project.operations.some((operation) =>
    operation.kind === "maker" && operation.status === "SUCCEEDED");
  const blockers = collectBlockers(project, connection, sections);
  const progress = {
    activeStage: project.stage,
    stagesReached: stageIndex(project.stage) + 1,
    stagesTotal: stageIds.length,
    sectionsApproved: approved,
    sectionsTotal: project.sections.length,
    label: progressLabel(project),
  };

  let readiness: ProjectOverview["readiness"];
  if (!connection || connection.state === "unavailable" || connection.state === "authentication_required" || connection.state === "incompatible_version") {
    readiness = {
      state: "blocked",
      label: "OpenCode needs attention",
      detail: "The saved project is intact. Repair the connection before Maker can run; completed stages stay inspectable.",
    };
  } else if (project.product.status !== "APPROVED") {
    readiness = {
      state: "blocked",
      label: "Product approval needed",
      detail: "The Oracle proposal is the gate for planning. Viewing later stages does not approve it.",
    };
  } else if (current || stale) {
    readiness = {
      state: "in_progress",
      label: "Planning in progress",
      detail: `${approved} of ${project.sections.length} sections are approved. ${current?.title ?? "A stale section"} is the next decision.`,
    };
  } else if (project.makerScope.status !== "GRANTED") {
    readiness = {
      state: "ready",
      label: "Plan ready",
      detail: "Every section is approved. Maker still waits for a separate execution scope.",
    };
  } else if (!makerSucceeded) {
    readiness = {
      state: activeRun ? "in_progress" : "ready",
      label: activeRun ? "Maker running" : "Ready for Maker",
      detail: activeRun
        ? "The durable run is in progress. Changing tabs or reloading will not repeat it."
        : "Execution scope is granted. Run the approved unit and inspect its real result.",
    };
  } else if (!project.witnessDrafts.length) {
    readiness = {
      state: "review",
      label: "Evidence ready for Witness",
      detail: "A Maker run succeeded. Review the evidence before preparing final materials.",
    };
  } else {
    readiness = {
      state: "review",
      label: "Drafts ready for review",
      detail: "Witness drafts are in-app review notes. Publication and submission remain separate actions.",
    };
  }

  const diagnostics = connection?.diagnostics ?? [];
  const diagnostic = diagnostics.find((item) => item.severity === "error")
    ?? diagnostics.find((item) => item.severity === "warning")
    ?? diagnostics[0];
  const openCode = {
    state: connection?.state ?? "unknown" as const,
    label: connectionLabel(connection?.state ?? "unknown"),
    detail: diagnostic?.message ?? (connection ? "OpenCode is reachable. A connection check is not an inference success." : "The saved connection state is still loading."),
    serverVersion: connection?.serverVersion ?? null,
    baseUrl: connection?.baseUrl ?? null,
    healthy: connection?.state === "connected" || connection?.state === "degraded",
  };

  const budget = {
    label: selectedModel
      ? selectedModel.pricing === "free"
        ? "Free model reported"
        : selectedModel.pricing === "paid"
          ? "Paid model reported"
          : "Price not reported"
      : "No model selected",
    detail: selectedModel
      ? "This app does not display a billed total. Quota and balance stay with the provider."
      : "Choose a model in OpenCode Setup before a Maker run.",
    model: selectedModel,
  };

  const nodeCheck = project.capabilities.find((capability) => capability.id === "node-check");
  const tools = {
    label: project.capabilities.length
      ? `${project.capabilities.filter((capability) => capability.availability === "available").length} available · ${project.capabilities.filter((capability) => capability.availability === "unknown").length} unknown`
      : "No tool observations",
    detail: nodeCheck
      ? `Node check: ${nodeCheck.availability}. ${nodeCheck.permission}.`
      : "No bounded tool has been recorded for this project.",
    nodeCheck: (nodeCheck?.availability ?? "unknown") as "available" | "unavailable" | "unknown",
    capabilities: project.capabilities.length,
  };

  const demo = {
    label: project.witnessDrafts.length
      ? `${project.witnessDrafts.length} draft${project.witnessDrafts.length === 1 ? "" : "s"} ready`
      : makerSucceeded
        ? "Evidence ready; no drafts"
        : latestEvidence
          ? "Evidence recorded; Maker incomplete"
          : "Not started",
    detail: latestEvidence
      ? `Latest check ${latestEvidence.checkId}: ${latestEvidence.result}.${latestEvidence.limitation ? ` ${latestEvidence.limitation}` : ""}`
      : "No check has been observed. A model statement cannot create a pass.",
    drafts: project.witnessDrafts.length,
    evidence: project.evidence.length,
  };

  return {
    readiness,
    progress,
    blockers,
    currentRun: runOverview(activeRun ?? latestRun),
    openCode,
    budget,
    tools,
    demo,
    nextAction: project.nextAction,
  };
}

export function buildStageView(
  project: WorkshopProject,
  connection: ConnectionStatus | null,
  selectedStage: StageId,
): StageView {
  const activeStage = project.stage;
  const relationship = stageRelationship(activeStage, selectedStage);
  const sections = buildSectionCards(project);
  const blockers = collectBlockers(project, connection, sections);
  const selectedModel = findSelectedModel(connection?.discovery ?? null, project.engine.model);
  const makerSucceeded = project.operations.some((operation) =>
    operation.kind === "maker" && operation.status === "SUCCEEDED");
  const current = project.sections.find((section) => section.id === project.currentSectionId) ?? null;
  const prerequisites: StagePrerequisite[] = (() => {
    switch (selectedStage) {
      case "ORACLE":
        return [{ label: stageMeta.ORACLE.prerequisites[0], met: true }];
      case "ARCHITECT":
        return [{ label: stageMeta.ARCHITECT.prerequisites[0], met: project.product.status === "APPROVED" }];
      case "MAKER":
        return [
          { label: stageMeta.MAKER.prerequisites[0], met: project.sections.length > 0 && !current && !sections.some((section) => section.state === "stale") },
          { label: stageMeta.MAKER.prerequisites[1], met: project.makerScope.status === "GRANTED" },
          { label: stageMeta.MAKER.prerequisites[2], met: Boolean(selectedModel) && (connection?.state === "connected" || connection?.state === "degraded") },
        ];
      case "WITNESS":
        return [
          { label: stageMeta.WITNESS.prerequisites[0], met: makerSucceeded },
          { label: stageMeta.WITNESS.prerequisites[1], met: project.evidence.length > 0 || project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED" && operation.result) },
        ];
    }
  })();
  const prerequisitesMet = prerequisites.every((prerequisite) => prerequisite.met);
  const canMutate = selectedStage === activeStage;
  return {
    selectedStage,
    activeStage,
    relationship,
    meta: stageMeta[selectedStage],
    progress: {
      activeStage,
      stagesReached: stageIndex(activeStage) + 1,
      stagesTotal: stageIds.length,
      sectionsApproved: sections.filter((section) => section.state === "approved").length,
      sectionsTotal: project.sections.length,
      label: progressLabel(project),
    },
    prerequisites,
    prerequisitesMet,
    canMutate,
    isReadOnly: !canMutate,
    notice: relationship === "completed"
      ? `You are reviewing the completed ${stageMeta[selectedStage].label} stage. Viewing it does not change an approval or repeat its work.`
      : relationship === "future"
        ? `You are previewing the future ${stageMeta[selectedStage].label} stage. Viewing it does not approve it, grant scope, or authorize execution.`
        : null,
    blockers,
    currentRun: runOverview(activeRunOf(project) ?? latestRunOf(project)),
    sections,
    nextAction: project.nextAction,
  };
}

