  const [announcement, setAnnouncement] = useState("");
  const [pendingFocus, setPendingFocus] = useState(false);

  useEffect(() => {
    const sync = () => {
      const raw = new URLSearchParams(window.location.search).get("view");
      setSelectedStage(resolveSelectedStage(raw, activeStage));
    };
    window.addEventListener("popstate", sync);
    return () => window.removeEventListener("popstate", sync);
  }, [activeStage]);

  useEffect(() => {
    const raw = new URLSearchParams(window.location.search).get("view");
    if (!parseStageView(raw)) setSelectedStage(activeStage);
    // If the selected stage becomes active due to a mutation, keep it.
  }, [activeStage]);

  useEffect(() => {
    if (!pendingFocus) return;
    document.getElementById("stage-title")?.focus();
    setPendingFocus(false);
  }, [selectedStage, pendingFocus]);

  function selectStage(stage: StageId, options?: { focusDocument?: boolean }) {
    setSelectedStage(stage);
    if (typeof window !== "undefined") {
      const href = viewHref(stage, window.location.search);
      window.history.pushState({}, "", href);
