    window.addEventListener("popstate", sync);
    return () => window.removeEventListener("popstate", sync);
  }, [activeStage]);

  useEffect(() => {
    const raw = new URLSearchParams(window.location.search).get("view");
    if (!parseStageView(raw)) setSelectedStage(activeStage);
    // If the selected stage becomes active due to a mutation, keep it.
  }, [activeStage]);

  useEffect(() => {
    if (!pendingFocus) return;
    document.getElementById("stage-title")?.focus();
    setPendingFocus(false);
  }, [selectedStage, pendingFocus]);

  function selectStage(stage: StageId, options?: { focusDocument?: boolean }) {
    setSelectedStage(stage);
    if (typeof window !== "undefined") {
      const href = viewHref(stage, window.location.search);
      window.history.pushState({}, "", href);
    }
    setAnnouncement(`${stageMeta[stage].label} tab selected. ${stage === activeStage ? "This is the active stage." : `The active stage remains ${stageMeta[activeStage].label}.`}`);
    if (options?.focusDocument) setPendingFocus(true);
  }
  return { selectedStage, selectStage, announcement };
}
```
Issue: `useEffect` on activeStage with no explicit param sets selected to active, but if user selected a tab we pushed URL param, so raw is valid and won't override. Good. If user navigated back to no param, popstate sets active. Good.
Initial URL no param: selected active, no URL. On reload, active. Good. If active changes and no param, selected follows. Good.
- `setAnnouncement` maybe same string; fine.
- `window` exists in browser; tests may render components not App.

For section navigation:
```
function goToSection(href: string) {
  const url = new URL(href, window.location.origin);
  const stage = parseStageView(url.searchParams.get("view")) ?? selectedStage;
  selectStage(stage);
  if (url.hash) setTimeout(() => document.querySelector(url.hash)?.scrollIntoView(...), 0);
}
```
But `selectStage` pushState without hash. We need preserve hash. Modify selectStage to accept `hash` and use `viewHref` plus hash:
```
function navigate(stage, hash) { ... history.pushState({}, "", viewHref(stage, window.location.search) + (hash ?? "")); }
```
Use for stage tabs no hash. For section cards, `onNavigate(card.action.href)`.

Let's create:
```
function navigateTo(stage: StageId, hash = "", focusDocument = false) { ... }
```
Then `selectStage` alias.

`SectionCard` onClick:
```
if (card.action.enabled) { e.preventDefault(); navigateTo("ARCHITECT", `#section-${card.id}`, false); }
```
But for approved cards action href has `?view=architect#section-id`. Good.
For locked/blocked, render `<span className="action locked" aria-disabled="true">...`.
Need stage tabs on click:
```
onClick={(event) => { if (event.metaKey||event.ctrlKey||event.shiftKey||event.altKey) return; event.preventDefault(); navigateTo(stage); }}
```
This allows open in new tab.
`aria-current` selected.

`header` content: We can compute `view = buildStageView(project, connection, selectedStage)`, `overview = buildProjectOverview(project, connection)`.
`headerTitle`:
