import { Eye, Hammer, ScrollText, Sparkles } from "lucide-react";
import {
  stageAriaLabel,
  stageIds,
  stageMeta,
  stageRelationship,
  stageRelationshipLabel,
  viewHref,
  type StageId,
} from "./workspace-view.ts";

const stageIcons = {
  ORACLE: Sparkles,
  ARCHITECT: ScrollText,
  MAKER: Hammer,
  WITNESS: Eye,
} as const;

export function StageTabs(props: {
  activeStage: StageId;
  selectedStage: StageId;
  onSelect?: (stage: StageId) => void;
}) {
  return (
    <nav className="stage-strip" aria-label="Spirit stages">
      {stageIds.map((stage) => {
        const Icon = stageIcons[stage];
        const relationship = stageRelationship(props.activeStage, stage);
        const selected = props.selectedStage === stage;
        return (
          <a
            key={stage}
            href={viewHref(stage)}
            className={`stage stage-${relationship}${selected ? " selected" : ""}`}
            aria-current={selected ? "page" : undefined}
            aria-label={stageAriaLabel(stage, relationship)}
            onClick={(event) => {
              if (!props.onSelect) return;
              if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
              event.preventDefault();
              props.onSelect?.(stage);
            }}
          >
            <Icon aria-hidden="true" size={18} />
            <span className="stage-label">{stageMeta[stage].label}</span>
            <span className="stage-state">{stageRelationshipLabel(relationship)}</span>
            {relationship === "active" ? <span className="stage-badge">Active</span> : null}
          </a>
        );
      })}
    </nav>
  );
}

import { Eye, Hammer, ScrollText, Sparkles } from "lucide-react";
import {
