import { useEffect, useMemo, useState } from "react";
import { Eye, Hammer, Lock, RefreshCw, ScrollText, Settings2, Sparkles } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import type { ConnectionStatus } from "../shared/opencode.ts";
import {
  ApiError,
  approveProduct,
  approveSection,
  cancelRun,
  findSelectedModel,
  grantScope,
  loadConnection,
  loadExport,
  loadProject,
  reconcileRun,
  reviseSection,
  runMaker,
  sendMessage,
  type WorkshopProject,
} from "./api.ts";
import { Onboarding } from "./onboarding.tsx";
import { OpenCodePanel } from "./opencode-panel.tsx";
import { StageTabs } from "./stage-navigation.tsx";
import {
  activeRunOf,
  activeStageBadge,
  buildProjectOverview,
  buildSectionCards,
  buildStageView,
  parseStageView,
  progressLabel,
  resolveSelectedStage,
  stageMeta,
  stageRelationshipLabel,
  unknownRunOf,
  viewHref,
  type ProjectOverview,
  type RunOverview,
  type SectionCardView,
  type StageId,
  type StageView,
} from "./workspace-view.ts";

const stageHeader: Record<StageId, string> = {
  ORACLE: "What's still haunting your to-do list?",
  ARCHITECT: "Turn the approved product into a plan",
  MAKER: "Run the approved unit, then inspect what happened",
  WITNESS: "Review the evidence before the demo",
};

const stageReviewHeader: Record<StageId, string> = {
  ORACLE: "Oracle: the approved product",
  ARCHITECT: "Architect: the project sections",
  MAKER: "Maker: the saved run record",
  WITNESS: "Witness: review notes and launch status",
};

export function App() {
  const [project, setProject] = useState<WorkshopProject | null>(null);
  const [connection, setConnection] = useState<ConnectionStatus | null>(null);
  const [setupOpen, setSetupOpen] = useState(false);
  const [text, setText] = useState("");
  const [scope, setScope] = useState("Build the approved plan in the isolated demo workspace and leave a passing Node test.");
  const [change, setChange] = useState("");
  const [busy, setBusy] = useState(false);
  const [slow, setSlow] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [exportNote, setExportNote] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();
  const activeStage = project?.stage ?? "ORACLE";
  const { selectedStage, navigate, announcement } = useSelectedStage(activeStage);

  useEffect(() => {
    let mounted = true;
    void (async () => {
      const [projectResult, connectionResult] = await Promise.allSettled([loadProject(), loadConnection()]);
      if (!mounted) return;
      if (projectResult.status === "fulfilled") {
        setProject(projectResult.value);
      } else {
        setError(projectResult.reason instanceof Error
          ? projectResult.reason.message
          : "The saved project could not be loaded.");
      }
      if (connectionResult.status === "fulfilled") {
        setConnection(connectionResult.value);
        if (projectResult.status === "fulfilled") {
          setSetupOpen(!connectionResult.value.discovery || !projectResult.value.engine.model);
        }
      } else {
        setConnection(unavailableConnection(connectionResult.reason));
        setSetupOpen(false);
      }
    })();
    return () => { mounted = false; };
  }, []);

  const activeRun = useMemo(() => (project ? activeRunOf(project) : null), [project]);
  const unknownRun = useMemo(() => (project ? unknownRunOf(project) : null), [project]);

  useEffect(() => {
    if (!activeRun) return;
    const timer = window.setInterval(() => {
      void loadProject().then(setProject).catch(() => {
        // A transient poll failure must not replace the visible project state.
      });
    }, 1_500);
    return () => window.clearInterval(timer);
  }, [activeRun?.id]);

  async function act(work: () => Promise<{ project: WorkshopProject }>) {
    setBusy(true);
    setSlow(false);
    setError(null);
    const timer = window.setTimeout(() => setSlow(true), 8_000);
    try {
      const result = await work();
      setProject(result.project);
    } catch (caught) {
      const loaded = await loadProject().catch(() => null);
      if (loaded) setProject(loaded);
      setError(caught instanceof ApiError
        ? `${caught.message} ${caught.retryable ? "You can try a new request. The saved section was not overwritten." : "Nothing was repeated."}`
        : "The workshop lost its connection. Reload before trying again.");
    } finally {
      window.clearTimeout(timer);
      setBusy(false);
      setSlow(false);
    }
  }

  if (!project || !connection) {
    return (
      <main className="workshop loading" aria-busy="true" aria-live="polite">
        <h1>Unfinished Business</h1>
        <p role="status">The workshop is waking up. Loading the saved project and OpenCode connection…</p>
        {error ? (
          <>
            <p className="banner bad" role="alert">{error}</p>
            <button className="action" type="button" onClick={() => window.location.reload()}>
              <RefreshCw aria-hidden="true" size={16} /> Reload the workshop
            </button>
          </>
        ) : null}
      </main>
    );
  }

  const firstRun = !connection.discovery || !project.engine.model;
  if (setupOpen || (firstRun && connection.state !== "unavailable")) {
    return (
      <main className="workshop">
        <header className="workshop-header">
          <div className="brand-row">
            <span className="brand"><Sparkles size={18} aria-hidden="true" /> Unfinished Business</span>
            <span className="active-badge" role="status">{activeStageBadge(project.stage)}</span>
          </div>
        </header>
        <Onboarding
          connection={connection}
          project={project}
          firstRun={firstRun}
          onConnection={(status) => {
            setConnection(status);
            if (status.discovery && project.engine.model) setSetupOpen(false);
          }}
          onProject={(updated) => {
            setProject(updated);
            if (updated.engine.model) setSetupOpen(false);
          }}
          onClose={() => setSetupOpen(false)}
        />
        {error ? <p className="banner bad" role="alert">{error}</p> : null}
      </main>
    );
  }

  const view = buildStageView(project, connection, selectedStage);
  const overview = buildProjectOverview(project, connection);
  const sections = buildSectionCards(project);
  const currentSection = project.sections.find((item) => item.id === project.currentSectionId) ?? null;
  const selectedModel = findSelectedModel(connection.discovery, project.engine.model);
  const header = view.relationship === "active"
    ? stageHeader[selectedStage]
    : `${stageReviewHeader[selectedStage]}`;
  const makerRunBlocked = project.stage !== "MAKER"
    ? "Maker is not the active stage."
    : !selectedModel
      ? "Choose a reported model in OpenCode Setup before running Maker."
      : connection.state !== "connected" && connection.state !== "degraded"
        ? "Repair the OpenCode connection before running Maker."
        : project.makerScope.status !== "GRANTED"
          ? "Grant a separate Maker scope before running."
          : activeRun
            ? "A run is already active."
            : null;
  const witnessReviewBlocked = project.stage !== "WITNESS"
    ? "Witness is not the active stage."
    : !project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED")
      ? "Wait for a successful Maker run."
      : null;

  function navigateTo(stage: StageId, options?: { hash?: string; focusDocument?: boolean }) {
    navigate(stage, options);
  }

  return (
    <>
      <div className="skip-links">
        <a className="skip" href="#project-overview">Skip to project overview</a>
        <a className="skip" href="#project-sections">Skip to project sections</a>
        <a className="skip" href="#document">Skip to the working document</a>
      </div>
      <main className="workshop" aria-busy={busy}>
        <header className="workshop-header">
          <div className="brand-row">
            <span className="brand"><Sparkles size={18} aria-hidden="true" /> Unfinished Business</span>
            <span className="active-badge" role="status">{activeStageBadge(project.stage)}</span>
            <p className="progress-summary">{progressLabel(project)}</p>
            <div className="header-actions">
              {selectedStage !== project.stage ? (
                <button className="action secondary" type="button" onClick={() => navigateTo(project.stage, { focusDocument: true })}>
                  Return to active task
                </button>
              ) : null}
              <button className="action secondary settings-button" type="button" onClick={() => setSetupOpen(true)}>
                <Settings2 size={16} aria-hidden="true" /> OpenCode
              </button>
            </div>
          </div>
          <StageTabs activeStage={project.stage} selectedStage={selectedStage} onSelect={(stage) => navigateTo(stage)} />
          <p className="sr-only" role="status" aria-live="polite">{announcement}</p>
        </header>

        <div className="frame">
          <aside className="side side-left" aria-label="Project context">
            <ProjectOverviewPanel overview={overview} onOpenSetup={() => setSetupOpen(true)} />
            <SectionMap
              sections={sections}
              evidenceCount={project.evidence.length}
              activeStage={project.stage}
              selectedStage={selectedStage}
              onNavigate={(href) => navigateHref(href, navigateTo, selectedStage)}
            />
          </aside>

          <article className="document" id="document" aria-busy={busy} aria-labelledby="stage-title">
            <div className="document-heading">
              <Lantern />
              <div>
                <p className="eyebrow">{stageMeta[selectedStage].label} · {stageRelationshipLabel(view.relationship)}</p>
                <h1 id="stage-title" tabIndex={-1}>{header}</h1>
              </div>
            </div>
            <p className="status-line">
              <strong>Active task:</strong> {project.nextAction}
            </p>
            <p className="meta">
              Viewing {stageMeta[selectedStage].label}. {selectedStage === project.stage
                ? "Permitted actions for the active stage are available below."
                : `The active stage remains ${stageMeta[project.stage].label}. Viewing this tab does not approve it or grant permission.`}
            </p>

            {view.notice ? (
              <div className="stage-notice" role="note">
                <Lock aria-hidden="true" size={18} />
                <p>{view.notice}</p>
                {selectedStage !== project.stage ? (
                  <button className="action secondary" type="button" onClick={() => navigateTo(project.stage, { focusDocument: true })}>
                    Return to active task
                  </button>
                ) : null}
              </div>
            ) : null}

            {connection.state !== "connected" && connection.state !== "degraded" ? (
              <p className="banner bad" role="status">
                OpenCode is {overview.openCode.label.toLowerCase()}. {overview.openCode.detail}{" "}
                <button className="action secondary" type="button" onClick={() => setSetupOpen(true)}>Open setup</button>
              </p>
            ) : connection.state === "degraded" ? (
              <p className="banner" role="status">
                OpenCode is connected with warnings. {overview.openCode.detail}{" "}
                <button className="action secondary" type="button" onClick={() => setSetupOpen(true)}>Review</button>
              </p>
            ) : null}
            {!selectedModel && project.engine.model ? (
              <p className="banner bad" role="status">
                The selected model is not in the current OpenCode catalog. Choose a reported model before a run.
                <button className="action secondary" type="button" onClick={() => setSetupOpen(true)}>Choose model</button>
              </p>
            ) : null}
            {activeRun ? (
              <p className="banner" role="status">
                <strong>{activeRun.kind === "maker" ? "Maker" : "OpenCode"}</strong> is working in the background
                {activeRun.model ? ` with ${activeRun.model.providerID}/${activeRun.model.id}` : ""}. The saved project updates when it finishes.
                <button className="action secondary" type="button" disabled={busy} onClick={() => void act(() => cancelRun(project, activeRun.id))}>Cancel run</button>
              </p>
            ) : null}
            {unknownRun ? (
              <p className="banner bad" role="status">
                A native run is unknown and was not repeated.
                <button className="action secondary" type="button" disabled={busy} onClick={() => void act(() => reconcileRun(project, unknownRun.id))}>Reconcile native session</button>
              </p>
            ) : null}
            {slow ? <p className="banner" role="status">This is taking longer than usual. The saved section is unchanged until a response arrives.</p> : null}
            {error ? <p className="banner bad" role="alert">{error}</p> : null}

            {selectedStage === "ORACLE" ? (
              view.relationship === "active" ? (
                <OraclePanel project={project} text={text} setText={setText} busy={busy} act={act} />
              ) : (
                <OracleReview project={project} view={view} reduceMotion={reduceMotion} />
              )
            ) : null}
            {selectedStage === "ARCHITECT" ? (
              view.relationship === "active" ? (
                currentSection ? (
                  <ArchitectPanel
                    project={project}
                    section={currentSection}
                    change={change}
                    setChange={setChange}
                    text={text}
                    setText={setText}
                    busy={busy}
                    act={act}
                    reduceMotion={reduceMotion}
                  />
                ) : (
                  <ScopePanel project={project} scope={scope} setScope={setScope} busy={busy} act={act} />
                )
              ) : (
                <ArchitectReview project={project} view={view} sections={sections} reduceMotion={reduceMotion} />
              )
            ) : null}
            {selectedStage === "MAKER" ? (
              view.relationship === "active" ? (
                <MakerPanel
                  project={project}
                  busy={busy}
                  activeRun={activeRun}
                  act={act}
                  onChooseModel={() => setSetupOpen(true)}
                  blockedReason={makerRunBlocked}
                  overview={overview}
                />
              ) : (
                <MakerReview project={project} view={view} />
              )
            ) : null}
            {selectedStage === "WITNESS" ? (
              view.relationship === "active" ? (
                <WitnessPanel
                  project={project}
                  text={text}
                  setText={setText}
                  busy={busy}
                  act={act}
                  exportNote={exportNote}
                  setExportNote={setExportNote}
                  blockedReason={witnessReviewBlocked}
                />
              ) : (
                <WitnessReview project={project} view={view} />
              )
            ) : null}

            <NextActionFooter project={project} view={view} onReturn={() => navigateTo(project.stage, { focusDocument: true })} />
          </article>

          <aside className="side side-right" aria-label="Activity and evidence">
            <Activity project={project} />
          </aside>
        </div>

        <OpenCodePanel
          connection={connection}
          project={project}
          onConnection={setConnection}
          onProject={setProject}
          onOpenSetup={() => setSetupOpen(true)}
        />
      </main>
    </>
  );
}

function useSelectedStage(activeStage: StageId) {
  const [selectedStage, setSelectedStage] = useState<StageId>(() =>
    resolveSelectedStage(new URLSearchParams(window.location.search).get("view"), activeStage));
  const [announcement, setAnnouncement] = useState("");
  const [focusDocument, setFocusDocument] = useState(false);

  useEffect(() => {
    const sync = () => {
      const raw = new URLSearchParams(window.location.search).get("view");
      setSelectedStage(resolveSelectedStage(raw, activeStage));
    };
    window.addEventListener("popstate", sync);
    return () => window.removeEventListener("popstate", sync);
  }, [activeStage]);

  useEffect(() => {
    const raw = new URLSearchParams(window.location.search).get("view");
    if (!parseStageView(raw)) setSelectedStage(activeStage);
  }, [activeStage]);

  useEffect(() => {
    if (!focusDocument) return;
    document.getElementById("stage-title")?.focus();
    setFocusDocument(false);
  }, [selectedStage, focusDocument]);

  function navigate(stage: StageId, options?: { hash?: string; focusDocument?: boolean }) {
    setSelectedStage(stage);
    const href = `${viewHref(stage, window.location.search)}${options?.hash ?? ""}`;
    window.history.pushState({}, "", href);
    setAnnouncement(`${stageMeta[stage].label} tab selected. ${stage === activeStage
      ? "This is the active workflow stage."
      : `The active workflow stage remains ${stageMeta[activeStage].label}.`}`);
    if (options?.focusDocument) setFocusDocument(true);
  }

  return { selectedStage, navigate, announcement };
}

function navigateHref(
  href: string,
  navigate: (stage: StageId, options?: { hash?: string; focusDocument?: boolean }) => void,
  fallback: StageId,
) {
  const parsed = new URL(href, window.location.origin);
  const stage = parseStageView(parsed.searchParams.get("view")) ?? fallback;
  navigate(stage, { hash: parsed.hash || undefined });
}

function unavailableConnection(reason: unknown): ConnectionStatus {
  const message = reason instanceof Error ? reason.message : "The saved connection state could not be loaded.";
  return {
    state: "unavailable",
    baseUrl: null,
    deploymentMode: "local",
    managed: false,
    auth: { mode: "none", username: "", hasPassword: false },
    serverVersion: null,
    compatible: null,
    checkedAt: null,
    diagnostics: [{
      code: "CONNECTION_STATUS_UNAVAILABLE",
      severity: "error",
      title: "OpenCode state unavailable",
      message,
      repair: "Open setup and test the OpenCode server again. A saved run or project is not hidden by this failure.",
    }],
    discovery: null,
  };
}

