  return (
    <>
      <p>Every current section is approved. Maker still needs a separate scope before any native edit.</p>
      <p className="muted">Granting scope is an explicit workflow action. Viewing the Maker tab does not grant it.</p>
      <label>
        Maker scope
        <textarea value={props.scope} onChange={(event) => props.setScope(event.target.value)} maxLength={2000} />
      </label>
      <button className="action" type="button" disabled={props.busy || props.scope.trim().length < 8} onClick={() => void props.act(() => grantScope(props.project, props.scope.trim()))}>
        Grant Maker scope
      </button>
    </>
  );
}

function MakerPanel(props: {
  project: WorkshopProject;
  busy: boolean;
  activeRun: WorkshopProject["operations"][number] | null;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
  onChooseModel: () => void;
  blockedReason: string | null;
  overview: ProjectOverview;
}) {
  const recommended = props.project.capabilities.find((item) => item.id === "node-check");
  const selected = props.project.engine.model;
  return (
    <>
      <p>Scope: {props.project.makerScope.statement}</p>
      <p className="meta">
        Chosen model: {selected ? `${selected.providerID}/${selected.id}${selected.variant ? `#${selected.variant}` : ""}` : "none selected"}. This model is recorded in the run evidence.
      </p>
      {recommended ? (
        <p className="banner">Recommended path: {recommended.purpose}. {recommended.nativeMapping}. Permission: {recommended.permission}.</p>
      ) : null}
      {props.blockedReason ? (
        <p className="banner bad" role="note">{props.blockedReason}</p>
      ) : null}
      <button className="action" type="button" disabled={props.busy || Boolean(props.blockedReason) || Boolean(props.activeRun)} onClick={() => void props.act(() => runMaker(props.project))}>
        {props.activeRun ? "Maker is running…" : "Run Maker"}
      </button>
      {!selected ? (
        <button className="action secondary" type="button" onClick={props.onChooseModel}>Choose model</button>
      ) : null}
      {props.activeRun ? <p className="note">The HTTP request returns immediately. Polling reads the persisted operation until OpenCode finishes.</p> : null}
      <p className="meta">
        OpenCode: {props.overview.openCode.label}. Budget: {props.overview.budget.label}. Tools: {props.overview.tools.label}.
      </p>
    </>
  );
}

function WitnessPanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
  exportNote: string | null;
  setExportNote: (value: string | null) => void;
  blockedReason: string | null;
}) {
  return (
    <>
      <p>Witness reads the evidence in a fresh session and writes review notes. Those notes are not a submitted article or video.</p>
      {props.blockedReason ? <p className="banner bad" role="note">{props.blockedReason}</p> : null}
      <label>
        What should Witness examine?
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        <button className="action" type="button" disabled={props.busy || Boolean(props.blockedReason) || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "witness", props.text))}>
          Review evidence
        </button>
        <button className="action secondary" type="button" disabled={props.busy} onClick={() => void loadExport().then((exported) => props.setExportNote(exported.limitation + (exported.plan ? " Compiled plan is ready." : " Plan is not fully approved."))).catch((caught: unknown) => props.setExportNote(caught instanceof Error ? caught.message : "Export failed."))}>
          Check export
        </button>
      </div>
      {props.exportNote ? <p className="banner" role="status">{props.exportNote}</p> : null}
      {props.project.witnessDrafts.map((draft) => (
        <section key={draft.id} className="reading">
          <h2>{draft.title}</h2>
          <p className="prose">{draft.content}</p>
        </section>
      ))}
    </>
  );
}

function Activity({ project }: { project: WorkshopProject }) {
  const latest = [...project.operations].toReversed().slice(0, 6);
  return (
    <>
      <section className="panel" id="activity" aria-labelledby="activity-heading">
        <h2 id="activity-heading">Activity</h2>
        {latest.length === 0 ? <p className="muted">No native run yet.</p> : (
          <ul>
            {latest.map((item) => (
              <li key={item.id}>
                <span className="meta">{item.kind} · {item.status}{item.model ? ` · ${item.model.providerID}/${item.model.id}${item.model.variant ? `#${item.model.variant}` : ""}` : ""}</span>
                <div className="evidence">{(item.result ?? "No result recorded.").slice(0, 280)}</div>
              </li>
            ))}
          </ul>
        )}
      </section>
      <section className="panel" id="evidence" aria-labelledby="evidence-heading">
        <h2 id="evidence-heading">Evidence</h2>
        {project.evidence.length === 0 ? <p className="muted">No check has been observed.</p> : (
          <ul>
            {project.evidence.map((item) => (
              <li key={item.id}>
                {item.checkId}: {item.result}{item.limitation ? ` — ${item.limitation}` : ""}
                {item.model ? <span className="meta"> · {item.model.providerID}/{item.model.id}</span> : null}
              </li>
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

function Seal({ label, reduceMotion }: { label: string; reduceMotion: boolean | null }) {
  if (reduceMotion) return <span className="seal">{label}</span>;
  return <motion.span className="seal" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }}>{label}</motion.span>;
}

function Lantern() {
  return (
    <svg className="lantern" viewBox="0 0 32 32" aria-hidden="true">
      <rect x="12" y="3" width="8" height="3" rx="1" fill="#f4b66c" />
      <path d="M10 8h12l-1 16H11L10 8z" fill="#252031" stroke="#f4b66c" />
      <circle className="flame" cx="16" cy="16" r="3" fill="#f4b66c" />
    </svg>
  );
}

function formatWhen(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
}

import { useEffect, useMemo, useState } from "react";
import { Eye, Hammer, Lock, RefreshCw, ScrollText, Settings2, Sparkles } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import type { ConnectionStatus } from "../shared/opencode.ts";
import {
  ApiError,
  approveProduct,
  approveSection,
  cancelRun,
  findSelectedModel,
  grantScope,
  loadConnection,
  loadExport,
  loadProject,
  reconcileRun,
  reviseSection,
  runMaker,
  sendMessage,
  type WorkshopProject,
} from "./api.ts";
import { Onboarding } from "./onboarding.tsx";
import { OpenCodePanel } from "./opencode-panel.tsx";
import { StageTabs } from "./stage-navigation.tsx";
import {
  activeRunOf,
  activeStageBadge,
  buildProjectOverview,
  buildSectionCards,
  buildStageView,
  parseStageView,
  progressLabel,
  resolveSelectedStage,
  stageMeta,
  stageRelationshipLabel,
  unknownRunOf,
  viewHref,
  type ProjectOverview,
  type RunOverview,
  type SectionCardView,
  type StageId,
  type StageView,
} from "./workspace-view.ts";

const stageHeader: Record<StageId, string> = {
  ORACLE: "What's still haunting your to-do list?",
  ARCHITECT: "Turn the approved product into a plan",
  MAKER: "Run the approved unit, then inspect what happened",
  WITNESS: "Review the evidence before the demo",
};

const stageReviewHeader: Record<StageId, string> = {
  ORACLE: "Oracle: the approved product",
  ARCHITECT: "Architect: the project sections",
  MAKER: "Maker: the saved run record",
  WITNESS: "Witness: review notes and launch status",
};

export function App() {
  const [project, setProject] = useState<WorkshopProject | null>(null);
  const [connection, setConnection] = useState<ConnectionStatus | null>(null);
  const [setupOpen, setSetupOpen] = useState(false);
  const [text, setText] = useState("");
  const [scope, setScope] = useState("Build the approved plan in the isolated demo workspace and leave a passing Node test.");
  const [change, setChange] = useState("");
  const [busy, setBusy] = useState(false);
  const [slow, setSlow] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [exportNote, setExportNote] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();
  const activeStage = project?.stage ?? "ORACLE";
  const { selectedStage, navigate, announcement } = useSelectedStage(activeStage);

  useEffect(() => {
    let mounted = true;
    void (async () => {
      const [projectResult, connectionResult] = await Promise.allSettled([loadProject(), loadConnection()]);
      if (!mounted) return;
      if (projectResult.status === "fulfilled") {
        setProject(projectResult.value);
      } else {
        setError(projectResult.reason instanceof Error
          ? projectResult.reason.message
          : "The saved project could not be loaded.");
      }
      if (connectionResult.status === "fulfilled") {
        setConnection(connectionResult.value);
        if (projectResult.status === "fulfilled") {
          setSetupOpen(!connectionResult.value.discovery || !projectResult.value.engine.model);
        }
      } else {
        setConnection(unavailableConnection(connectionResult.reason));
        setSetupOpen(false);
      }
    })();
    return () => { mounted = false; };
  }, []);

  const activeRun = useMemo(() => (project ? activeRunOf(project) : null), [project]);
  const unknownRun = useMemo(() => (project ? unknownRunOf(project) : null), [project]);

  useEffect(() => {
    if (!activeRun) return;
    const timer = window.setInterval(() => {
      void loadProject().then(setProject).catch(() => {
        // A transient poll failure must not replace the visible project state.
      });
    }, 1_500);
    return () => window.clearInterval(timer);
  }, [activeRun?.id]);

  async function act(work: () => Promise<{ project: WorkshopProject }>) {
    setBusy(true);
    setSlow(false);
    setError(null);
    const timer = window.setTimeout(() => setSlow(true), 8_000);
    try {
      const result = await work();
      setProject(result.project);
    } catch (caught) {
      const loaded = await loadProject().catch(() => null);
      if (loaded) setProject(loaded);
      setError(caught instanceof ApiError
        ? `${caught.message} ${caught.retryable ? "You can try a new request. The saved section was not overwritten." : "Nothing was repeated."}`
        : "The workshop lost its connection. Reload before trying again.");
    } finally {
      window.clearTimeout(timer);
      setBusy(false);
      setSlow(false);
    }
  }

  if (!project || !connection) {
    return (
      <main className="workshop loading" aria-busy="true" aria-live="polite">
        <h1>Unfinished Business</h1>
        <p role="status">The workshop is waking up. Loading the saved project and OpenCode connection…</p>
        {error ? (
          <>
            <p className="banner bad" role="alert">{error}</p>
            <button className="action" type="button" onClick={() => window.location.reload()}>
              <RefreshCw aria-hidden="true" size={16} /> Reload the workshop
            </button>
          </>
        ) : null}
      </main>
    );
  }

  const firstRun = !connection.discovery || !project.engine.model;
  if (setupOpen || (firstRun && connection.state !== "unavailable")) {
    return (
      <main className="workshop">
        <header className="workshop-header">
          <div className="brand-row">
            <span className="brand"><Sparkles size={18} aria-hidden="true" /> Unfinished Business</span>
            <span className="active-badge" role="status">{activeStageBadge(project.stage)}</span>
          </div>
        </header>
        <Onboarding
          connection={connection}
          project={project}
          firstRun={firstRun}
          onConnection={(status) => {
            setConnection(status);
            if (status.discovery && project.engine.model) setSetupOpen(false);
          }}
          onProject={(updated) => {
            setProject(updated);
            if (updated.engine.model) setSetupOpen(false);
          }}
          onClose={() => setSetupOpen(false)}
        />
        {error ? <p className="banner bad" role="alert">{error}</p> : null}
      </main>
    );
  }

  const view = buildStageView(project, connection, selectedStage);
  const overview = buildProjectOverview(project, connection);
  const sections = buildSectionCards(project);
  const currentSection = project.sections.find((item) => item.id === project.currentSectionId) ?? null;
  const selectedModel = findSelectedModel(connection.discovery, project.engine.model);
  const header = view.relationship === "active"
    ? stageHeader[selectedStage]
    : `${stageReviewHeader[selectedStage]}`;
  const makerRunBlocked = project.stage !== "MAKER"
    ? "Maker is not the active stage."
    : !selectedModel
      ? "Choose a reported model in OpenCode Setup before running Maker."
      : connection.state !== "connected" && connection.state !== "degraded"
        ? "Repair the OpenCode connection before running Maker."
        : project.makerScope.status !== "GRANTED"
          ? "Grant a separate Maker scope before running."
          : activeRun
            ? "A run is already active."
            : null;
  const witnessReviewBlocked = project.stage !== "WITNESS"
    ? "Witness is not the active stage."
    : !project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED")
      ? "Wait for a successful Maker run."
      : null;

  function navigateTo(stage: StageId, options?: { hash?: string; focusDocument?: boolean }) {
    navigate(stage, options);
  }

  return (
    <>
      <div className="skip-links">
        <a className="skip" href="#project-overview">Skip to project overview</a>
        <a className="skip" href="#project-sections">Skip to project sections</a>
        <a className="skip" href="#document">Skip to the working document</a>
      </div>
      <main className="workshop" aria-busy={busy}>
        <header className="workshop-header">
          <div className="brand-row">
            <span className="brand"><Sparkles size={18} aria-hidden="true" /> Unfinished Business</span>
            <span className="active-badge" role="status">{activeStageBadge(project.stage)}</span>
            <p className="progress-summary">{progressLabel(project)}</p>
            <div className="header-actions">
              {selectedStage !== project.stage ? (
                <button className="action secondary" type="button" onClick={() => navigateTo(project.stage, { focusDocument: true })}>
                  Return to active task
                </button>
              ) : null}
              <button className="action secondary settings-button" type="button" onClick={() => setSetupOpen(true)}>
                <Settings2 size={16} aria-hidden="true" /> OpenCode
              </button>
            </div>
          </div>
          <StageTabs activeStage={project.stage} selectedStage={selectedStage} onSelect={(stage) => navigateTo(stage)} />
          <p className="sr-only" role="status" aria-live="polite">{announcement}</p>
        </header>

        <div className="frame">
          <aside className="side side-left" aria-label="Project context">
            <ProjectOverviewPanel overview={overview} onOpenSetup={() => setSetupOpen(true)} />
            <SectionMap
              sections={sections}
              evidenceCount={project.evidence.length}
              activeStage={project.stage}
              selectedStage={selectedStage}
              onNavigate={(href) => navigateHref(href, navigateTo, selectedStage)}
            />
          </aside>

          <article className="document" id="document" aria-busy={busy} aria-labelledby="stage-title">
            <div className="document-heading">
              <Lantern />
              <div>
                <p className="eyebrow">{stageMeta[selectedStage].label} · {stageRelationshipLabel(view.relationship)}</p>
                <h1 id="stage-title" tabIndex={-1}>{header}</h1>
              </div>
            </div>
            <p className="status-line">
              <strong>Active task:</strong> {project.nextAction}
            </p>
            <p className="meta">
              Viewing {stageMeta[selectedStage].label}. {selectedStage === project.stage
                ? "Permitted actions for the active stage are available below."
                : `The active stage remains ${stageMeta[project.stage].label}. Viewing this tab does not approve it or grant permission.`}
            </p>

            {view.notice ? (
              <div className="stage-notice" role="note">
                <Lock aria-hidden="true" size={18} />
                <p>{view.notice}</p>
                {selectedStage !== project.stage ? (
                  <button className="action secondary" type="button" onClick={() => navigateTo(project.stage, { focusDocument: true })}>
                    Return to active task
                  </button>
                ) : null}
              </div>
            ) : null}

            {connection.state !== "connected" && connection.state !== "degraded" ? (
              <p className="banner bad" role="status">
                OpenCode is {overview.openCode.label.toLowerCase()}. {overview.openCode.detail}{" "}
                <button className="action secondary" type="button" onClick={() => setSetupOpen(true)}>Open setup</button>
              </p>
            ) : connection.state === "degraded" ? (
              <p className="banner" role="status">
                OpenCode is connected with warnings. {overview.openCode.detail}{" "}
                <button className="action secondary" type="button" onClick={() => setSetupOpen(true)}>Review</button>
              </p>
            ) : null}
            {!selectedModel && project.engine.model ? (
              <p className="banner bad" role="status">
                The selected model is not in the current OpenCode catalog. Choose a reported model before a run.
                <button className="action secondary" type="button" onClick={() => setSetupOpen(true)}>Choose model</button>
              </p>
            ) : null}
            {activeRun ? (
              <p className="banner" role="status">
                <strong>{activeRun.kind === "maker" ? "Maker" : "OpenCode"}</strong> is working in the background
                {activeRun.model ? ` with ${activeRun.model.providerID}/${activeRun.model.id}` : ""}. The saved project updates when it finishes.
                <button className="action secondary" type="button" disabled={busy} onClick={() => void act(() => cancelRun(project, activeRun.id))}>Cancel run</button>
              </p>
            ) : null}
            {unknownRun ? (
              <p className="banner bad" role="status">
                A native run is unknown and was not repeated.
                <button className="action secondary" type="button" disabled={busy} onClick={() => void act(() => reconcileRun(project, unknownRun.id))}>Reconcile native session</button>
              </p>
            ) : null}
            {slow ? <p className="banner" role="status">This is taking longer than usual. The saved section is unchanged until a response arrives.</p> : null}
            {error ? <p className="banner bad" role="alert">{error}</p> : null}

            {selectedStage === "ORACLE" ? (
              view.relationship === "active" ? (
                <OraclePanel project={project} text={text} setText={setText} busy={busy} act={act} />
              ) : (
                <OracleReview project={project} view={view} reduceMotion={reduceMotion} />
              )
            ) : null}
            {selectedStage === "ARCHITECT" ? (
              view.relationship === "active" ? (
                currentSection ? (
                  <ArchitectPanel
                    project={project}
                    section={currentSection}
                    change={change}
                    setChange={setChange}
                    text={text}
                    setText={setText}
                    busy={busy}
                    act={act}
                    reduceMotion={reduceMotion}
                  />
                ) : (
                  <ScopePanel project={project} scope={scope} setScope={setScope} busy={busy} act={act} />
                )
              ) : (
                <ArchitectReview project={project} view={view} sections={sections} reduceMotion={reduceMotion} />
              )
            ) : null}
            {selectedStage === "MAKER" ? (
              view.relationship === "active" ? (
                <MakerPanel
                  project={project}
                  busy={busy}
                  activeRun={activeRun}
                  act={act}
                  onChooseModel={() => setSetupOpen(true)}
                  blockedReason={makerRunBlocked}
                  overview={overview}
                />
              ) : (
                <MakerReview project={project} view={view} />
              )
            ) : null}
            {selectedStage === "WITNESS" ? (
              view.relationship === "active" ? (
                <WitnessPanel
                  project={project}
                  text={text}
                  setText={setText}
                  busy={busy}
                  act={act}
                  exportNote={exportNote}
                  setExportNote={setExportNote}
                  blockedReason={witnessReviewBlocked}
                />
              ) : (
                <WitnessReview project={project} view={view} />
              )
            ) : null}

            <NextActionFooter project={project} view={view} onReturn={() => navigateTo(project.stage, { focusDocument: true })} />
          </article>

          <aside className="side side-right" aria-label="Activity and evidence">
            <Activity project={project} />
          </aside>
        </div>

        <OpenCodePanel
          connection={connection}
          project={project}
          onConnection={setConnection}
          onProject={setProject}
          onOpenSetup={() => setSetupOpen(true)}
        />
      </main>
    </>
  );
}

function useSelectedStage(activeStage: StageId) {
  const [selectedStage, setSelectedStage] = useState<StageId>(() =>
    resolveSelectedStage(new URLSearchParams(window.location.search).get("view"), activeStage));
  const [announcement, setAnnouncement] = useState("");
  const [focusDocument, setFocusDocument] = useState(false);

  useEffect(() => {
    const sync = () => {
      const raw = new URLSearchParams(window.location.search).get("view");
      setSelectedStage(resolveSelectedStage(raw, activeStage));
    };
    window.addEventListener("popstate", sync);
    return () => window.removeEventListener("popstate", sync);
  }, [activeStage]);

  useEffect(() => {
    const raw = new URLSearchParams(window.location.search).get("view");
    if (!parseStageView(raw)) setSelectedStage(activeStage);
  }, [activeStage]);

  useEffect(() => {
    if (!focusDocument) return;
    document.getElementById("stage-title")?.focus();
    setFocusDocument(false);
  }, [selectedStage, focusDocument]);

  function navigate(stage: StageId, options?: { hash?: string; focusDocument?: boolean }) {
    setSelectedStage(stage);
    const href = `${viewHref(stage, window.location.search)}${options?.hash ?? ""}`;
    window.history.pushState({}, "", href);
    setAnnouncement(`${stageMeta[stage].label} tab selected. ${stage === activeStage
      ? "This is the active workflow stage."
      : `The active workflow stage remains ${stageMeta[activeStage].label}.`}`);
    if (options?.focusDocument) setFocusDocument(true);
  }

  return { selectedStage, navigate, announcement };
}

function navigateHref(
  href: string,
  navigate: (stage: StageId, options?: { hash?: string; focusDocument?: boolean }) => void,
  fallback: StageId,
) {
  const parsed = new URL(href, window.location.origin);
  const stage = parseStageView(parsed.searchParams.get("view")) ?? fallback;
  navigate(stage, { hash: parsed.hash || undefined });
}

function unavailableConnection(reason: unknown): ConnectionStatus {
  const message = reason instanceof Error ? reason.message : "The saved connection state could not be loaded.";
  return {
    state: "unavailable",
    baseUrl: null,
    deploymentMode: "local",
    managed: false,
    auth: { mode: "none", username: "", hasPassword: false },
    serverVersion: null,
    compatible: null,
    checkedAt: null,
    diagnostics: [{
      code: "CONNECTION_STATUS_UNAVAILABLE",
      severity: "error",
      title: "OpenCode state unavailable",
      message,
      repair: "Open setup and test the OpenCode server again. A saved run or project is not hidden by this failure.",
    }],
    discovery: null,
  };
}

function ProjectOverviewPanel(props: { overview: ProjectOverview; onOpenSetup: () => void }) {
  const { overview } = props;
  return (
    <section className="panel overview" id="project-overview" aria-labelledby="overview-heading">
      <h2 id="overview-heading">Project overview</h2>
      <p className={`readiness readiness-${overview.readiness.state}`}>
        <span className="readiness-label">{overview.readiness.label}</span>
        <span>{overview.readiness.detail}</span>
      </p>
      <p className="meta">{overview.progress.label}</p>

      <div className="overview-grid">
        <section aria-labelledby="overview-run">
          <h3 id="overview-run">Current run</h3>
          {overview.currentRun ? (
            <RunSummary run={overview.currentRun} />
          ) : <p className="muted">No native run has been saved.</p>}
        </section>
        <section aria-labelledby="overview-opencode">
          <h3 id="overview-opencode">OpenCode state</h3>
          <p><span className={`pill state-${overview.openCode.healthy ? "approved" : "stale"}`}>{overview.openCode.label}</span></p>
          <p className="muted">{overview.openCode.detail}</p>
          <p className="meta">
            {overview.openCode.serverVersion ? `Server ${overview.openCode.serverVersion}` : "Version not reported"}
            {overview.openCode.baseUrl ? ` · ${overview.openCode.baseUrl}` : ""}
          </p>
          {!overview.openCode.healthy ? (
            <button className="action secondary" type="button" onClick={props.onOpenSetup}>Open setup</button>
          ) : null}
        </section>
        <section aria-labelledby="overview-budget">
          <h3 id="overview-budget">Budget & tools</h3>
          <p><strong>{overview.budget.label}</strong></p>
          <p className="muted">{overview.budget.detail}</p>
          <p className="meta">{overview.tools.label} · {overview.tools.detail}</p>
        </section>
        <section aria-labelledby="overview-demo">
          <h3 id="overview-demo">Demo status</h3>
          <p><strong>{overview.demo.label}</strong></p>
          <p className="muted">{overview.demo.detail}</p>
          <p className="meta">{overview.demo.drafts} draft(s) · {overview.demo.evidence} observed check(s)</p>
        </section>
      </div>

      <section className="blockers" aria-labelledby="overview-blockers">
        <h3 id="overview-blockers">Active blockers</h3>
        {overview.blockers.length === 0 ? (
          <p className="muted">No active blockers are recorded. Continue with the next action below.</p>
        ) : (
          <ul>
            {overview.blockers.map((blocker) => (
              <li key={blocker.id}>
                <span className={`pill stage-tag stage-${blocker.stage === "ALL" ? "active" : blocker.stage.toLowerCase()}`}>
                  {blocker.stage === "ALL" ? "Global" : stageMeta[blocker.stage].label}
                </span>
                <strong>{blocker.label}</strong>
                <span>{blocker.detail}</span>
              </li>
            ))}
          </ul>
        )}
      </section>
      <p className="next-action"><strong>Next action:</strong> {overview.nextAction}</p>
    </section>
  );
}

function RunSummary({ run }: { run: RunOverview }) {
  return (
    <div className="run-summary">
      <p><span className={`pill state-${run.status.toLowerCase()}`}>{run.status}</span> {run.kind}</p>
      <p className="meta">
        {run.model ?? "Model not recorded"}
        {run.startedAt ? ` · started ${formatWhen(run.startedAt)}` : ""}
        {run.finishedAt ? ` · finished ${formatWhen(run.finishedAt)}` : ""}
      </p>
      {run.result ? <p className="evidence">{run.result.slice(0, 320)}</p> : <p className="muted">No result recorded.</p>}
      {run.canReconcile ? <p className="muted">Unknown outcome. Reconcile the native session before another attempt.</p> : null}
    </div>
  );
}

function SectionMap(props: {
  sections: SectionCardView[];
  evidenceCount: number;
  activeStage: StageId;
  selectedStage: StageId;
  onNavigate: (href: string) => void;
}) {
  return (
    <section className="panel sections" id="project-sections" aria-labelledby="sections-heading">
      <h2 id="sections-heading">Project sections</h2>
      <p className="muted">Eight stable planning areas. Labels can change; approvals and content hashes do not.</p>
      <ol className="section-list">
        {props.sections.map((section) => (
          <li key={section.id}>
            <SectionCard
              section={section}
              evidenceCount={props.evidenceCount}
              onNavigate={props.onNavigate}
            />
          </li>
        ))}
      </ol>
    </section>
  );
}

function SectionCard(props: { section: SectionCardView; evidenceCount: number; onNavigate: (href: string) => void }) {
  const { section } = props;
  return (
    <article
      className={`section-card section-${section.state}`}
      id={`section-${section.id}`}
      aria-labelledby={`section-${section.id}-title`}
      aria-current={section.isCurrent ? "step" : undefined}
    >
      <header className="section-card-head">
        <p className="meta">Section {section.order} · {section.owner}</p>
        <h3 id={`section-${section.id}-title`}>{section.title}</h3>
        <p>
          <span className={`pill state-${section.state}`}>{section.stateLabel}</span>
          <span className="pill">{section.statusLabel}</span>
        </p>
      </header>
      <p className="section-summary">{section.summary}</p>
      <dl className="section-meta">
        <div><dt>Version</dt><dd>{section.version > 0 ? `v${section.version}` : "No draft"}</dd></div>
        <div><dt>Last update</dt><dd>{section.lastUpdate ? formatWhen(section.lastUpdate) : "Not updated yet"}</dd></div>
      </dl>
      <div className="dependencies">
        <h4>Dependencies</h4>
        {section.dependencies.length === 0 ? <p className="muted">None.</p> : (
          <ul>
            {section.dependencies.map((dependency) => (
              <li key={dependency.id} className={dependency.met ? "met" : "unmet"}>
                {dependency.title} — {dependency.met ? "approved" : "not approved"}
              </li>
            ))}
          </ul>
        )}
      </div>
      {section.staleReason ? (
        <p className="stale-reason" role="note"><strong>Stale reason:</strong> {section.staleReason}</p>
      ) : null}
      {section.approval ? (
        <p className="approval-line" id={`section-${section.id}-approval`}>
          <strong>Approval:</strong> v{section.approval.version} on {formatWhen(section.approval.approvedAt)}
          {section.approval.staleReason ? ` · ${section.approval.staleReason}` : ""}
        </p>
      ) : null}
      <p className="evidence-link" id={`section-${section.id}-evidence`}>
        <a href="#evidence">Evidence: {props.evidenceCount} observed check(s)</a>
      </p>
      {section.action.enabled ? (
        <a
          className="action secondary section-action"
          href={section.action.href}
          onClick={(event) => {
            if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
            event.preventDefault();
            props.onNavigate(section.action.href);
          }}
        >
          {section.action.label}
        </a>
      ) : (
        <span className="action locked" aria-disabled="true">
          <Lock aria-hidden="true" size={14} /> {section.action.label}
        </span>
      )}
    </article>
  );
}

function OracleReview(props: { project: WorkshopProject; view: StageView; reduceMotion: boolean | null }) {
  const approved = props.project.product.status === "APPROVED";
  return (
    <>
      {props.view.relationship === "future" ? <StagePreview view={props.view} /> : null}
      {approved ? (
        <section className="reading" aria-labelledby="oracle-approved">
          <h2 id="oracle-approved">Approved product proposal <Seal label="Approved" reduceMotion={props.reduceMotion} /></h2>
          <p className="prose">{props.project.product.proposal}</p>
          {props.project.product.openQuestions.length ? (
            <>
              <h3>Recorded open questions</h3>
              <ul>{props.project.product.openQuestions.map((question) => <li key={question}>{question}</li>)}</ul>
            </>
          ) : <p className="muted">No open questions are recorded.</p>}
        </section>
      ) : (
        <p className="banner">The Oracle has not stored a proposal yet. This review shows the stage purpose without approving anything.</p>
      )}
      <StagePreview view={props.view} />
    </>
  );
}

function ArchitectReview(props: {
  project: WorkshopProject;
  view: StageView;
  sections: SectionCardView[];
  reduceMotion: boolean | null;
}) {
  const approved = props.sections.filter((section) => section.state === "approved");
  return (
    <>
      <StagePreview view={props.view} />
      <section className="reading" aria-labelledby="architect-artifacts">
        <h2 id="architect-artifacts">Approved sections</h2>
        {approved.length === 0 ? (
          <p className="muted">No section is approved yet. The left project map shows which sections are locked or blocked.</p>
        ) : (
          <div className="artifact-list">
            {approved.map((section) => (
              <details key={section.id} className="artifact">
                <summary>
                  {section.order}. {section.title} <span className="pill state-approved">Approved v{section.version}</span>
                </summary>
                <p className="prose">{section.content}</p>
                {section.approval ? (
                  <p className="meta">Approved {formatWhen(section.approval.approvedAt)}. Hash retained; viewing does not re-approve.</p>
                ) : null}
              </details>
            ))}
          </div>
        )}
      </section>
      <section className="reading" aria-labelledby="architect-preview">
        <h2 id="architect-preview">Section map preview</h2>
        <ol className="preview-sections">
          {props.sections.map((section) => (
            <li key={section.id}>
              <strong>{section.order}. {section.title}</strong> — {section.stateLabel}
              {section.blockedBy.length ? <span className="muted"> · blocked by {section.blockedBy.join(", ")}</span> : null}
            </li>
          ))}
        </ol>
      </section>
    </>
  );
}

function MakerReview(props: { project: WorkshopProject; view: StageView }) {
  const runs = props.project.operations.filter((operation) => operation.kind === "maker");
  return (
    <>
      <StagePreview view={props.view} />
      <section className="reading" aria-labelledby="maker-runs">
        <h2 id="maker-runs">Saved Maker runs</h2>
        {runs.length === 0 ? (
          <p className="muted">No Maker run exists yet. Opening this tab did not create a run or grant scope.</p>
        ) : (
          <div className="run-history">
            {runs.toReversed().map((run) => (
              <article key={run.id} className="run-card">
                <h3>{run.kind} · {run.status}</h3>
                <p className="meta">
                  {run.model ? `${run.model.providerID}/${run.model.id}${run.model.variant ? `#${run.model.variant}` : ""}` : "Model not recorded"}
                  {run.startedAt ? ` · ${formatWhen(run.startedAt)}` : ""}
                </p>
                <p className="evidence prose">{run.result ?? "No result recorded."}</p>
              </article>
            ))}
          </div>
        )}
      </section>
      <section className="reading" aria-labelledby="maker-evidence">
        <h2 id="maker-evidence">Observed evidence</h2>
        {props.project.evidence.length === 0 ? (
          <p className="muted">No check has been observed. A model statement cannot create a pass.</p>
        ) : (
          <ul>
            {props.project.evidence.map((evidence) => (
              <li key={evidence.id}>{evidence.checkId}: {evidence.result}{evidence.limitation ? ` — ${evidence.limitation}` : ""}</li>
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

function WitnessReview(props: { project: WorkshopProject; view: StageView }) {
  return (
    <>
      <StagePreview view={props.view} />
      <section className="reading" aria-labelledby="witness-drafts">
        <h2 id="witness-drafts">Witness drafts</h2>
        {props.project.witnessDrafts.length === 0 ? (
          <p className="muted">No Witness drafts exist yet. The saved evidence remains inspectable from the Activity panel.</p>
        ) : (
          props.project.witnessDrafts.map((draft) => (
            <section key={draft.id} className="reading">
              <h3>{draft.title}</h3>
              <p className="prose">{draft.content}</p>
            </section>
          ))
        )}
      </section>
    </>
  );
}

function StagePreview(props: { view: StageView }) {
  return (
    <section className="stage-preview" aria-labelledby="stage-purpose">
      <h2 id="stage-purpose">What this stage does</h2>
      <p>{props.view.meta.purpose}</p>
      <div className="preview-grid">
        <section>
          <h3>Prerequisites</h3>
          <ul className="prereq-list">
            {props.view.prerequisites.map((prerequisite) => (
              <li key={prerequisite.label} className={prerequisite.met ? "met" : "unmet"}>
                {prerequisite.met ? "Met" : "Waiting"} — {prerequisite.label}
              </li>
            ))}
          </ul>
        </section>
        <section>
          <h3>Expected output</h3>
          <p>{props.view.meta.expectedOutput}</p>
        </section>
        <section>
          <h3>Preview</h3>
          <p>{props.view.meta.preview}</p>
        </section>
      </div>
      <p className="locked-note" role="note">
        <Lock aria-hidden="true" size={16} /> {props.view.isReadOnly
          ? "Actions stay locked on this tab. Viewing is not approval, execution scope, or permission."
          : "Only this active stage can use its permitted actions."}
      </p>
    </section>
  );
}

function NextActionFooter(props: { project: WorkshopProject; view: StageView; onReturn: () => void }) {
  return (
    <footer className="next-footer">
      <p><strong>Next action:</strong> {props.project.nextAction}</p>
      <p className="meta">
        {props.view.relationship === "active"
          ? "You are on the active stage."
          : `You are inspecting a ${props.view.relationship} stage. The workflow state is unchanged.`}
      </p>
      {props.view.relationship !== "active" ? (
        <button className="action" type="button" onClick={props.onReturn}>Return to active task</button>
      ) : null}
    </footer>
  );
}

function OraclePanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  const proposal = props.project.product.proposal;
  return (
    <>
      <p>Describe an idea you want to bring to life. The Oracle clarifies; it cannot approve the product for you.</p>
      {proposal ? (
        <div className="reading prose">
          <h2>Oracle proposal</h2>
          <p>{proposal}</p>
          {props.project.product.openQuestions.length ? (
            <ul>{props.project.product.openQuestions.map((question) => <li key={question}>{question}</li>)}</ul>
          ) : null}
        </div>
      ) : null}
      <label>
        Idea or question
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        {proposal ? (
          <button className="action" type="button" disabled={props.busy} onClick={() => void props.act(() => approveProduct(props.project))}>
            Approve product
          </button>
        ) : (
          <button className="action" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "clarify", props.text))}>
            Wake the Oracle
          </button>
        )}
        {proposal ? (
          <button className="action secondary" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "question", props.text))}>
            Ask a question
          </button>
        ) : null}
      </div>
    </>
  );
}

function ArchitectPanel(props: {
  project: WorkshopProject;
  section: WorkshopProject["sections"][number];
  change: string;
  setChange: (value: string) => void;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  reduceMotion: boolean | null;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  const cards = buildSectionCards(props.project);
  const card = cards.find((item) => item.id === props.section.id);
  return (
    <>
      <p className="meta">
        Section {props.section.order} of {props.project.sections.length} · {props.section.status} · version {props.section.version}
      </p>
      <p className="muted">Viewing or drafting this section does not approve it. Approval applies only to the exact current version and hash.</p>
      {card?.staleReason ? <p className="banner" role="note"><strong>Stale reason:</strong> {card.staleReason}</p> : null}
      <div className="reading prose" id={`section-${props.section.id}`}>
        {props.section.content || "This section has no draft yet."}
      </div>
      {card?.approval ? (
        <p className="approval-line" id={card.approvalLink}>
          <strong>Previous approval:</strong> v{card.approval.version} on {formatWhen(card.approval.approvedAt)}
        </p>
      ) : null}
      {props.section.status === "APPROVED" ? <Seal label="Section approved" reduceMotion={props.reduceMotion} /> : null}
      <div className="actions">
        <button className="action" type="button" disabled={props.busy} onClick={() => void props.act(() => sendMessage(props.project, "draft", props.text.trim() || `Draft ${props.section.title}`))}>
          Draft section
        </button>
        {props.section.status === "DRAFT" ? (
          <button className="action secondary" type="button" disabled={props.busy} onClick={() => void props.act(() => approveSection(props.project, props.section.version, props.section.hash, props.section.id))}>
            Approve section
          </button>
        ) : null}
      </div>
      <label>
        Ask a question
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <button className="action secondary" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "question", props.text))}>
        Ask
      </button>
      <label>
        Replacement text for this section
        <textarea value={props.change} onChange={(event) => props.setChange(event.target.value)} maxLength={8000} />
      </label>
      <button className="action secondary" type="button" disabled={props.busy || props.change.trim().length < 1} onClick={() => void props.act(() => reviseSection(props.project, props.section.id, props.change))}>
        Request changes
      </button>
    </>
  );
}

function ScopePanel(props: {
  project: WorkshopProject;
  scope: string;
  setScope: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  return (
    <>
      <p>Every current section is approved. Maker still needs a separate scope before any native edit.</p>
      <p className="muted">Granting scope is an explicit workflow action. Viewing the Maker tab does not grant it.</p>
      <label>
        Maker scope
        <textarea value={props.scope} onChange={(event) => props.setScope(event.target.value)} maxLength={2000} />
      </label>
      <button className="action" type="button" disabled={props.busy || props.scope.trim().length < 8} onClick={() => void props.act(() => grantScope(props.project, props.scope.trim()))}>
        Grant Maker scope
      </button>
    </>
  );
}

function MakerPanel(props: {
  project: WorkshopProject;
  busy: boolean;
  activeRun: WorkshopProject["operations"][number] | null;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
  onChooseModel: () => void;
  blockedReason: string | null;
  overview: ProjectOverview;
}) {
  const recommended = props.project.capabilities.find((item) => item.id === "node-check");
  const selected = props.project.engine.model;
  return (
    <>
      <p>Scope: {props.project.makerScope.statement}</p>
      <p className="meta">
        Chosen model: {selected ? `${selected.providerID}/${selected.id}${selected.variant ? `#${selected.variant}` : ""}` : "none selected"}. This model is recorded in the run evidence.
      </p>
      {recommended ? (
        <p className="banner">Recommended path: {recommended.purpose}. {recommended.nativeMapping}. Permission: {recommended.permission}.</p>
      ) : null}
      {props.blockedReason ? (
        <p className="banner bad" role="note">{props.blockedReason}</p>
      ) : null}
      <button className="action" type="button" disabled={props.busy || Boolean(props.blockedReason) || Boolean(props.activeRun)} onClick={() => void props.act(() => runMaker(props.project))}>
        {props.activeRun ? "Maker is running…" : "Run Maker"}
      </button>
      {!selected ? (
        <button className="action secondary" type="button" onClick={props.onChooseModel}>Choose model</button>
      ) : null}
      {props.activeRun ? <p className="note">The HTTP request returns immediately. Polling reads the persisted operation until OpenCode finishes.</p> : null}
      <p className="meta">
        OpenCode: {props.overview.openCode.label}. Budget: {props.overview.budget.label}. Tools: {props.overview.tools.label}.
      </p>
    </>
  );
}

function WitnessPanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
  exportNote: string | null;
  setExportNote: (value: string | null) => void;
  blockedReason: string | null;
}) {
  return (
    <>
      <p>Witness reads the evidence in a fresh session and writes review notes. Those notes are not a submitted article or video.</p>
      {props.blockedReason ? <p className="banner bad" role="note">{props.blockedReason}</p> : null}
      <label>
        What should Witness examine?
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        <button className="action" type="button" disabled={props.busy || Boolean(props.blockedReason) || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "witness", props.text))}>
          Review evidence
        </button>
        <button className="action secondary" type="button" disabled={props.busy} onClick={() => void loadExport().then((exported) => props.setExportNote(exported.limitation + (exported.plan ? " Compiled plan is ready." : " Plan is not fully approved."))).catch((caught: unknown) => props.setExportNote(caught instanceof Error ? caught.message : "Export failed."))}>
          Check export
        </button>
      </div>
      {props.exportNote ? <p className="banner" role="status">{props.exportNote}</p> : null}
      {props.project.witnessDrafts.map((draft) => (
        <section key={draft.id} className="reading">
          <h2>{draft.title}</h2>
          <p className="prose">{draft.content}</p>
        </section>
      ))}
    </>
  );
}

function Activity({ project }: { project: WorkshopProject }) {
  const latest = [...project.operations].toReversed().slice(0, 6);
  return (
    <>
      <section className="panel" id="activity" aria-labelledby="activity-heading">
        <h2 id="activity-heading">Activity</h2>
        {latest.length === 0 ? <p className="muted">No native run yet.</p> : (
          <ul>
            {latest.map((item) => (
              <li key={item.id}>
                <span className="meta">{item.kind} · {item.status}{item.model ? ` · ${item.model.providerID}/${item.model.id}${item.model.variant ? `#${item.model.variant}` : ""}` : ""}</span>
                <div className="evidence">{(item.result ?? "No result recorded.").slice(0, 280)}</div>
              </li>
            ))}
          </ul>
        )}
      </section>
      <section className="panel" id="evidence" aria-labelledby="evidence-heading">
        <h2 id="evidence-heading">Evidence</h2>
        {project.evidence.length === 0 ? <p className="muted">No check has been observed.</p> : (
          <ul>
            {project.evidence.map((item) => (
              <li key={item.id}>
                {item.checkId}: {item.result}{item.limitation ? ` — ${item.limitation}` : ""}
                {item.model ? <span className="meta"> · {item.model.providerID}/{item.model.id}</span> : null}
              </li>
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

function Seal({ label, reduceMotion }: { label: string; reduceMotion: boolean | null }) {
  if (reduceMotion) return <span className="seal">{label}</span>;
  return <motion.span className="seal" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }}>{label}</motion.span>;
}

function Lantern() {
  return (
    <svg className="lantern" viewBox="0 0 32 32" aria-hidden="true">
      <rect x="12" y="3" width="8" height="3" rx="1" fill="#f4b66c" />
      <path d="M10 8h12l-1 16H11L10 8z" fill="#252031" stroke="#f4b66c" />
      <circle className="flame" cx="16" cy="16" r="3" fill="#f4b66c" />
    </svg>
  );
}

function formatWhen(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
}

