    gap: var(--space-4);
    align-items: start;
  }
}

@media (min-width: 1240px) {
  .frame {
    grid-template-columns: 340px minmax(0, 1fr) 300px;
  }
}

/* Phase 3: inspectable workflow and project information architecture */
.workshop-header {
  display: grid;
  gap: var(--space-3);
  background: var(--surface);
  border: 1px solid rgb(244 240 232 / 12%);
  border-radius: 16px;
  padding: var(--space-3);
}

.brand-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
  min-width: 0;
}

.brand-row .brand {
  margin-right: 0;
}

.active-badge {
  border: 1px solid var(--accent);
  border-radius: 999px;
  color: var(--accent);
  padding: var(--space-1) var(--space-3);
  font-size: 0.8rem;
  font-weight: 650;
}

.progress-summary {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
  overflow-wrap: anywhere;
}

.header-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-left: auto;
}

.document-heading {
  display: flex;
  align-items: start;
  gap: var(--space-3);
}

.document-heading .lantern {
  width: 36px;
  height: 36px;
  margin-top: var(--space-2);
}

h3,
h4 {
  font-family: Georgia, "Iowan Old Style", serif;
  font-weight: 500;
}

h3 {
  margin: var(--space-4) 0 var(--space-2);
  font-size: 1.15rem;
}

h4 {
  margin: var(--space-3) 0 var(--space-1);
  font-size: 1rem;
}

.muted {
  color: var(--muted);
}

.stage-notice {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: var(--space-2) var(--space-3);
  align-items: start;
  margin-top: var(--space-4);
  padding: var(--space-3);
  border: 1px dashed var(--spirit);
  border-radius: 12px;
  color: var(--muted);
}

.stage-notice p {
  margin: 0;
}

.stage-notice .action {
  grid-column: 2;
  justify-self: start;
}

.stage-preview {
  margin-top: var(--space-4);
  padding: var(--space-4);
  border: 1px solid rgb(244 240 232 / 12%);
  border-radius: 16px;
  background: rgb(17 16 24 / 45%);
}

.preview-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--space-4);
}

.preview-grid section {
  min-width: 0;
}

.preview-grid h3 {
  margin-top: 0;
}

.prereq-list,
.blockers ul,
.dependencies ul,
.preview-sections,
.section-list {
  list-style: none;
  padding: 0;
  margin: var(--space-2) 0 0;
}

.prereq-list li,
.dependencies li,
.blockers li {
  padding: var(--space-1) 0;
  overflow-wrap: anywhere;
}

.prereq-list .met,
.dependencies .met {
  color: var(--success);
}

.prereq-list .unmet,
.dependencies .unmet {
  color: var(--danger);
}

.locked-note {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin: var(--space-3) 0 0;
  color: var(--muted);
}

.next-footer {
  margin-top: var(--space-5);
  padding-top: var(--space-4);
  border-top: 1px solid rgb(244 240 232 / 12%);
}

.next-footer p {
  margin: 0 0 var(--space-2);
}

.side-left,
.side-right {
  min-width: 0;
}

.overview .readiness {
  display: grid;
  gap: var(--space-1);
  padding: var(--space-3);
  border-radius: 12px;
  background: var(--raised);
  overflow-wrap: anywhere;
}

.readiness-label {
  font-weight: 700;
}

.readiness-blocked {
  border-left: 4px solid var(--danger);
}

.readiness-in_progress {
  border-left: 4px solid var(--accent);
}

.readiness-ready {
  border-left: 4px solid var(--success);
}

.readiness-review {
  border-left: 4px solid var(--spirit);
}

.overview-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: var(--space-3);
  margin-top: var(--space-3);
}

.overview-grid section {
  min-width: 0;
  padding: var(--space-2);
  border: 1px solid rgb(244 240 232 / 10%);
  border-radius: 12px;
}

.overview-grid h3 {
  margin-top: 0;
  font-size: 1rem;
}

.overview-grid p {
  margin: var(--space-1) 0;
  overflow-wrap: anywhere;
}

.blockers {
  margin-top: var(--space-4);
}

.blockers li {
  display: grid;
  gap: var(--space-1);
  padding: var(--space-2);
  border-bottom: 1px solid rgb(244 240 232 / 10%);
}

.next-action {
  margin-top: var(--space-4);
  padding: var(--space-3);
  border-radius: 12px;
  background: var(--raised);
  overflow-wrap: anywhere;
}

.pill {
  display: inline-block;
  margin: 0 var(--space-1) var(--space-1) 0;
  padding: 1px var(--space-2);
  border-radius: 999px;
  background: var(--raised);
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 650;
  white-space: normal;
}

.pill.state-approved,
.pill.state-succeeded {
  color: var(--success);
  border: 1px solid var(--success);
}

.pill.state-draft,
.pill.state-running,
.pill.state-queued,
.pill.state-waiting_permission {
  color: var(--accent);
  border: 1px solid var(--accent);
}

.pill.state-stale,
.pill.state-failed,
.pill.state-unknown,
.pill.state-unavailable {
  color: var(--danger);
  border: 1px solid var(--danger);
}

.pill.state-empty,
.pill.state-locked,
.pill.state-blocked {
  color: var(--muted);
  border: 1px solid rgb(184 175 202 / 40%);
}

.stage-tag {
  justify-self: start;
}

.section-list {
  display: grid;
  gap: var(--space-3);
  margin-top: var(--space-3);
}

.section-card {
  scroll-margin-top: var(--space-5);
  padding: var(--space-3);
  border: 1px solid rgb(244 240 232 / 12%);
  border-radius: 12px;
  background: rgb(17 16 24 / 35%);
  overflow-wrap: anywhere;
}

.section-card[aria-current="step"] {
  border-color: var(--accent);
}

.section-card.section-stale {
  border-style: dashed;
  border-color: var(--spirit);
}

.section-card.section-locked,
.section-card.section-blocked {
  opacity: 0.82;
}

.section-card-head h3 {
  margin: var(--space-1) 0;
  overflow-wrap: anywhere;
}

.section-card-head p {
  margin: 0;
}

.section-summary {
  margin: var(--space-2) 0;
}

.section-meta {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: var(--space-2);
  margin: var(--space-2) 0;
}

.section-meta div {
  min-width: 0;
}

.section-meta dt {
  color: var(--muted);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.section-meta dd {
  margin: 0;
}

.stale-reason {
  margin: var(--space-2) 0;
  padding: var(--space-2);
  border-radius: 8px;
  background: rgb(191 163 255 / 12%);
  color: var(--text);
}

.approval-line {
  margin: var(--space-2) 0;
  color: var(--success);
}

.evidence-link {
  margin: var(--space-2) 0;
}

.evidence-link a {
  color: var(--spirit);
}

.section-action {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  margin-top: var(--space-2);
  text-decoration: none;
}

.action.locked {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  margin-top: var(--space-2);
  background: var(--raised);
  color: var(--muted);
  cursor: not-allowed;
}

.artifact-list {
  display: grid;
  gap: var(--space-2);
}

.artifact {
  border: 1px solid rgb(244 240 232 / 12%);
  border-radius: 12px;
  padding: var(--space-2) var(--space-3);
}

.artifact summary {
  cursor: pointer;
  min-height: 32px;
}

.artifact .prose {
  margin-top: var(--space-2);
}

.preview-sections li {
  padding: var(--space-1) 0;
}

.run-history {
  display: grid;
  gap: var(--space-3);
}

.run-card {
  padding: var(--space-3);
  border: 1px solid rgb(244 240 232 / 12%);
  border-radius: 12px;
}

.run-card h3 {
  margin-top: 0;
}

.run-summary p {
  margin: var(--space-1) 0;
}

.loading {
  min-height: 50vh;
  align-content: start;
  justify-items: start;
}

.workshop.loading h1 {
  margin-bottom: var(--space-2);
}

/* Keep long technical values inside their panels at every width. */
.panel,
.document,
.section-card,
.stage-preview,
.onboarding,
.advanced {
  overflow-wrap: anywhere;
}

@media (max-width: 959px) {
  .frame {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-4);
  }

  .frame .document {
    order: 1;
  }

  .frame .side-left {
    order: 2;
  }

  .frame .side-right {
    order: 3;
  }

  .header-actions {
    margin-left: 0;
    width: 100%;
  }
}

@media (max-width: 620px) {
  .workshop {
    width: min(100% - 16px, 1120px);
    margin-top: var(--space-3);
  }

  .document {
    padding: var(--space-4);
  }

  .stage-strip {
    flex-wrap: nowrap;
    overflow-x: auto;
    padding-bottom: var(--space-2);
    scrollbar-width: thin;
  }

  .stage {
    flex: 0 0 auto;
  }

  .preview-grid,
  .overview-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .document-heading {
    gap: var(--space-2);
  }

  h1 {
    font-size: clamp(1.7rem, 9vw, 2.6rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

input.oldString:
@media (min-width: 960px) {
  .workshop {
    grid-template-columns: minmax(0, 1fr);
  }

  .frame {
    display: grid;
    grid-template-columns: 220px minmax(0, 1fr) 280px;
    gap: var(--space-4);
    align-items: start;
  }
}

