import { readFile } from "node:fs/promises";
import { resolve, sep } from "node:path";

export type Stage = "oracle" | "architect" | "maker" | "witness";

/**
 * The four runtime spirit procedures. Repository implementation prompts live
 * under `docs/prompts/implementation-phases/` and must never be loadable as a
 * spirit procedure. Keep this an explicit allow-list rather than a directory
 * scan so adding a build prompt cannot silently change runtime behavior.
 */
export const RUNTIME_PROMPT_FILES: Record<Stage, string> = {
  oracle: "Prompt-0-Product-Discovery-v5.1.md",
  architect: "PROMPT_1_ARCHITECT.md",
  maker: "Prompt-2-Build-and-Verify-v5.1.md",
  witness: "Prompt-3-Demo-and-Submission-v1.0.md",
};

export async function loadStagePrompt(stage: Stage, root = process.cwd()): Promise<string> {
  const filename = RUNTIME_PROMPT_FILES[stage];
  if (!filename || filename.includes("implementation-phases")) {
    throw new Error(`Prompt ${stage} is not a runtime spirit procedure.`);
  }
  const promptDirectory = resolve(root, "docs", "prompts");
  const path = resolve(promptDirectory, filename);
  if (!path.startsWith(`${promptDirectory}${sep}`)) {
    throw new Error(`Prompt ${stage} resolves outside the runtime prompt directory.`);
  }
  const content = await readFile(path, "utf8");
  if (content.length < 1_000) {
    throw new Error(`Prompt ${stage} is unexpectedly short; refusing to load a summary in place of the full procedure.`);
  }
  if (/^# Phase \d+ prompt/m.test(content)) {
    throw new Error(`Prompt ${stage} is a repository implementation prompt, not a runtime spirit procedure.`);
  }
  return content;
}

