import assert from "node:assert/strict";
import test from "node:test";
import { loadStagePrompt, RUNTIME_PROMPT_FILES, type Stage } from "../src/server/prompts/loader.ts";

for (const stage of ["oracle", "architect", "maker", "witness"] as const satisfies readonly Stage[]) {
  test(`loads the complete ${stage} procedure`, async () => {
    const content = await loadStagePrompt(stage);
    assert.match(content, /^# /);
    assert.ok(content.length > 5_000);
    assert.doesNotMatch(content, /^# Phase \d+ prompt/m);
    assert.doesNotMatch(content, /Implement only Phase \d+/);
  });
}

test("runtime prompt loading is an explicit allow-list that excludes implementation prompts", () => {
  assert.deepEqual(Object.keys(RUNTIME_PROMPT_FILES).sort(), ["architect", "maker", "oracle", "witness"]);
  for (const filename of Object.values(RUNTIME_PROMPT_FILES)) {
    assert.doesNotMatch(filename, /implementation|phase/i);
  }
});

