import assert from "node:assert/strict";
import test from "node:test";
import { approveSection, compileApprovedPlan, reviseSection, WorkflowConflict } from "../src/server/workflow/transitions.ts";
import { createProject, refreshNextAction, sectionDefinitions } from "../src/server/workflow/model.ts";

function started() {
  const project = createProject("/workspace");
  project.product = { status: "APPROVED", proposal: "Build the approved product.", openQuestions: [] };
  return refreshNextAction(project);
}

function approve(project: ReturnType<typeof createProject>, id: string, content = `${id} content`) {
  const drafted = reviseSection(project, id, content);
  const section = drafted.sections.find((item) => item.id === id)!;
  return approveSection(drafted, id, section.version, section.hash);
}

test("advances only after exact current-version approval", () => {
  const drafted = reviseSection(started(), "control", "scope v1");
  const section = drafted.sections[0];
  assert.throws(() => approveSection(drafted, "control", section.version, "stale"), WorkflowConflict);
  const approved = approveSection(drafted, "control", section.version, section.hash);
  assert.equal(approved.currentSectionId, "architecture");
});

test("upstream revision invalidates only transitive dependents", () => {
  let project = started();
  for (const section of project.sections) project = approve(project, section.id);
  project = reviseSection(project, "tools", "changed tools");
  assert.equal(project.sections.find((item) => item.id === "experience")?.status, "APPROVED");
  assert.equal(project.sections.find((item) => item.id === "readiness")?.status, "STALE");
  assert.equal(project.sections.find((item) => item.id === "verification")?.status, "STALE");
  assert.equal(project.sections.find((item) => item.id === "phases")?.status, "STALE");
  assert.equal(project.sections.find((item) => item.id === "delivery")?.status, "STALE");
});

test("future sections cannot be drafted ahead of the current section", () => {
  const project = started();
  assert.throws(
    () => reviseSection(project, "validation-unused", "future text"),
    /Unknown section/,
  );
  assert.throws(
    () => reviseSection(project, "verification", "future text"),
    /Only the current section or a previously approved section/,
  );
});

test("sections cannot be revised or approved before the Oracle product is approved", () => {
  const project = createProject("/workspace");
  assert.throws(
    () => reviseSection(project, "control", "premature"),
    /Oracle product is approved/,
  );
  const drafted = reviseSection(started(), "control", "scope");
  const section = drafted.sections[0];
  const notApproved = createProject("/workspace");
  notApproved.sections[0] = section;
  notApproved.currentSectionId = "control";
  assert.throws(
    () => approveSection(notApproved, "control", section.version, section.hash),
    /approved Oracle product/,
  );
});

test("compiles exact approved blocks only", () => {
  let project = started();
  assert.throws(() => compileApprovedPlan(project), WorkflowConflict);
  for (const section of project.sections) project = approve(project, section.id, `approved ${section.id}`);
  const plan = compileApprovedPlan(project);
  assert.match(plan, /approved control/);
  assert.match(plan, /approved delivery/);
  assert.doesNotMatch(plan, /approved readiness/);
  assert.match(plan, /## Vision & Success/);
  assert.match(plan, /## Demo & Launch/);
});

test("the eight user-facing sections keep stable internal ids and dependencies", () => {
  assert.deepEqual(sectionDefinitions.map(([id]) => id), [
    "control", "architecture", "experience", "tools", "readiness", "verification", "phases", "delivery",
  ]);
  assert.deepEqual(sectionDefinitions.map(([, title]) => title), [
    "Vision & Success", "Architecture", "User Experience", "OpenCode Setup",
    "Tools & Budget", "Validation", "Build Roadmap", "Demo & Launch",
  ]);
  assert.deepEqual(createProject("/workspace").sections.map((section) => section.order), [1, 2, 3, 4, 5, 6, 7, 8]);
});

