import assert from "node:assert/strict";
import { mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { AtomicProjectStore } from "../src/server/store/atomic-project-store.ts";
import {
  createProject,
  LEGACY_FIXED_MODEL_KEY,
  migrateProject,
  projectSchema,
  refreshNextAction,
} from "../src/server/workflow/model.ts";
import { approveSection, reviseSection } from "../src/server/workflow/transitions.ts";

const legacyTitles: Record<string, string> = {
  control: "Control, product, scope, and acceptance",
  architecture: "Architecture and contracts",
  experience: "Experience",
  tools: "Tools, access, and cost",
  verification: "Verification and risks",
  phases: "Phases and queue",
  delivery: "Delivery",
  readiness: "Execution directive and readiness",
};

const legacyDependencies: Record<string, string[]> = {
  control: [],
  architecture: ["control"],
  experience: ["control", "architecture"],
  tools: ["architecture"],
  verification: ["control", "architecture", "tools"],
  phases: ["verification"],
  delivery: ["experience", "verification", "phases"],
  readiness: ["control", "architecture", "experience", "tools", "verification", "phases", "delivery"],
};

const legacyOrder = ["control", "architecture", "experience", "tools", "verification", "phases", "delivery", "readiness"];

function legacyProject() {
  const current = createProject("/workspace");
  const { engine: _engine, ...rest } = current;
  return {
    ...rest,
    schemaVersion: 1,
    operations: [{
      id: "op-1",
      kind: "maker",
      payloadHash: "hash",
      nativeSessionId: "ses_old",
      nativeMessageId: "msg_old",
      status: "SUCCEEDED",
      result: "old result",
    }],
    evidence: [{
      id: "ev-1",
      checkId: "CK-06",
      nativeResultReference: "ses_old",
      testedFingerprint: "fingerprint",
      result: "PASS",
      observedAt: "2026-10-31T10:00:00.000Z",
      limitation: null,
    }],
    nativeSessions: [{ role: "maker", sessionId: "ses_old" }],
  };
}

function v2ProjectWithApprovals() {
  let project = createProject("/workspace");
  project.product = { status: "APPROVED", proposal: "Track found items.", openQuestions: [] };
  project = refreshNextAction(project);
  for (const id of ["control", "architecture"]) {
    project = reviseSection(project, id, `Approved ${id} content.`);
    const section = project.sections.find((item) => item.id === id)!;
    project = approveSection(project, id, section.version, section.hash);
  }
  const legacy = structuredClone(project) as unknown as Record<string, unknown>;
  legacy.schemaVersion = 2;
  legacy.sections = project.sections.map((section) => ({
    ...section,
    title: legacyTitles[section.id],
    order: legacyOrder.indexOf(section.id) + 1,
    dependencies: legacyDependencies[section.id],
  }));
  return { v2: legacy, before: project };
}

test("v1 fixed-model projects migrate to v3 without losing history", () => {
  const migrated = migrateProject(legacyProject());
  assert.equal(migrated.schemaVersion, 3);
  assert.equal(migrated.engine.model, null);
  assert.equal(migrated.engine.source, "migrated-legacy");
  assert.equal(migrated.engine.legacyModel, LEGACY_FIXED_MODEL_KEY);
  assert.equal(migrated.operations[0].id, "op-1");
  assert.equal(migrated.operations[0].model, null);
  assert.equal(migrated.operations[0].status, "SUCCEEDED");
  assert.equal(migrated.evidence[0].checkId, "CK-06");
  assert.equal(migrated.evidence[0].model, null);
  assert.equal(migrated.nativeSessions[0].sessionId, "ses_old");
  assert.deepEqual(migrated.sections.map((section) => section.id), legacyOrder);
  assert.deepEqual(migrated.sections.map((section) => section.title), [
    "Vision & Success", "Architecture", "User Experience", "OpenCode Setup",
    "Tools & Budget", "Validation", "Build Roadmap", "Demo & Launch",
  ]);
});

test("v2 display-label migration preserves approvals, hashes, content, and ids", () => {
  const { v2, before } = v2ProjectWithApprovals();
  const migrated = migrateProject(v2);
  assert.equal(migrated.schemaVersion, 3);
  assert.deepEqual(migrated.approvals, before.approvals);
  assert.equal(migrated.approvals.length, 2);
  assert.deepEqual(migrated.sections.map((section) => section.id), before.sections.map((section) => section.id));
  assert.deepEqual(migrated.sections.map((section) => section.title), [
    "Vision & Success", "Architecture", "User Experience", "OpenCode Setup",
    "Tools & Budget", "Validation", "Build Roadmap", "Demo & Launch",
  ]);
  const control = migrated.sections.find((section) => section.id === "control")!;
  const beforeControl = before.sections.find((section) => section.id === "control")!;
  assert.equal(control.hash, beforeControl.hash);
  assert.equal(control.content, beforeControl.content);
  assert.equal(control.version, beforeControl.version);
  assert.equal(control.status, "APPROVED");
  assert.equal(control.updatedAt, beforeControl.updatedAt);
  assert.equal(migrated.sections.find((section) => section.id === "readiness")?.order, 5);
  assert.deepEqual(
    migrated.sections.find((section) => section.id === "readiness")?.dependencies,
    ["control", "architecture", "tools"],
  );
});

test("loading and saving a migrated project persists schema v3", async () => {
  const directory = await mkdtemp(join(tmpdir(), "ub-migration-"));
  const path = join(directory, "project.json");
  await writeFile(path, JSON.stringify(legacyProject()), "utf8");
  const store = new AtomicProjectStore(path);
  const loaded = await store.load();
  assert.equal(loaded.state.schemaVersion, 3);
  loaded.state.product = { status: "APPROVED", proposal: "Migrated product.", openQuestions: [] };
  refreshNextAction(loaded.state);
  const revised = reviseSection(loaded.state, "control", "migrated scope");
  await store.save(loaded.state.revision, revised);
  const persisted = JSON.parse(await readFile(path, "utf8"));
  assert.equal(persisted.schemaVersion, 3);
  assert.equal(persisted.engine.legacyModel, LEGACY_FIXED_MODEL_KEY);
  assert.equal(projectSchema.parse(persisted).schemaVersion, 3);
  assert.equal(persisted.sections[0].title, "Vision & Success");
});

test("new projects start with no model selection and the current labels", () => {
  const project = createProject("/workspace");
  assert.equal(project.schemaVersion, 3);
  assert.equal(project.engine.model, null);
  assert.equal(project.engine.source, "none");
  assert.equal(project.engine.legacyModel, null);
  assert.deepEqual(project.sections.map((section) => section.title), [
    "Vision & Success", "Architecture", "User Experience", "OpenCode Setup",
    "Tools & Budget", "Validation", "Build Roadmap", "Demo & Launch",
  ]);
});

test("unsupported project schema versions fail visibly", () => {
  assert.throws(() => migrateProject({ schemaVersion: 99 }), /Unsupported project schema/);
  assert.throws(() => migrateProject(null), /not an object/);
});

