test("persists revision and exact approval through validated routes", async () => {
  const { app } = await fixture();
  const headers = { "content-type": "application/json", "x-ub-session-token": "test-token" };
  const revision = await app.request("/api/sections/control/revisions", {
    method: "POST", headers,
    body: JSON.stringify({ actionId: "revise", expectedRevision: 0, content: "approved scope" }),
  });
  assert.equal(revision.status, 200);
  const revised = await revision.json();
  const section = revised.project.sections[0];
  const approval = await app.request("/api/sections/control/approve", {
    method: "POST", headers,
    body: JSON.stringify({ actionId: "approve", expectedRevision: 1, version: section.version, hash: section.hash }),
  });
  assert.equal(approval.status, 200);
  const approved = await approval.json();
  assert.equal(approved.project.currentSectionId, "architecture");
});

test("direct view URLs are read-only and never change the active stage or revision", async () => {
  const { app, store } = await fixture();
  const before = (await store.load()).state;
  for (const view of ["maker", "witness", "oracle", "architect", "unknown"]) {
    const response = await app.request(`/api/project?view=${view}`);
    assert.equal(response.status, 200);
    const project = await response.json();
    assert.equal(project.stage, before.stage);
    assert.equal(project.revision, before.revision);
    assert.equal(project.currentSectionId, before.currentSectionId);
  }
});

test("server gates reject future section revisions and non-current approvals", async () => {
  const { app } = await fixture();
  const headers = { "content-type": "application/json", "x-ub-session-token": "test-token" };
  const futureRevision = await app.request("/api/sections/verification/revisions", {
    method: "POST", headers,
    body: JSON.stringify({ actionId: "future", expectedRevision: 0, content: "future section" }),
  });
  assert.equal(futureRevision.status, 409);

  const notCurrent = await app.request("/api/sections/architecture/approve", {
    method: "POST", headers,
    body: JSON.stringify({ actionId: "wrong-approval", expectedRevision: 0, version: 1, hash: "a".repeat(64) }),
  });
  assert.equal(notCurrent.status, 409);
});

