import assert from "node:assert/strict";
import test from "node:test";
import type { ConnectionStatus, OpenCodeDiscovery } from "../src/shared/opencode.ts";
import {
  buildProjectOverview,
  buildSectionCards,
  buildStageView,
  parseStageView,
  progressLabel,
  resolveSelectedStage,
  stageAriaLabel,
  stageRelationship,
  stageReached,
  viewHref,
} from "../src/web/workspace-view.ts";
import {
  createProject,
  refreshNextAction,
  type Project,
} from "../src/server/workflow/model.ts";
import { approveSection, reviseSection } from "../src/server/workflow/transitions.ts";
import type { WorkshopProject } from "../src/web/api.ts";

const model = {
  key: "opencode/flint-40b-free",
  providerID: "opencode",
  id: "flint-40b-free",
  name: "Flint 40B Free",
  family: "flint",
  availability: "available" as const,
  status: "active" as const,
  enabled: true,
  pricing: "free" as const,
  local: false,
  limits: { context: 100_000, input: null, output: 8_000 },
  modalities: { input: ["text"], output: ["text"] },
  tools: true,
  reasoning: { supported: true, source: "variants" as const },
  variants: ["low"],
  cost: [{ tierSize: null, input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }],
};

const discovery: OpenCodeDiscovery = {
  server: { version: "2.0.32", compatible: true, testedVersion: "2.0.32", warning: null },
  providers: [],
  models: [model],
  agents: [],
  roles: [],
  permissions: [],
  commands: [],
  skills: [],
  mcpServers: [],
  formatters: [],
  lspServers: [],
  capabilities: [],
  usage: { supported: true, quotaSupported: false, links: [], detail: "usage" },
  limitations: [],
};

function connection(state: ConnectionStatus["state"] = "connected"): ConnectionStatus {
  return {
    state,
    baseUrl: "http://127.0.0.1:4096",
    deploymentMode: "local",
    managed: false,
    auth: { mode: "none", username: "", hasPassword: false },
    serverVersion: state === "unavailable" ? null : "2.0.32",
    compatible: state === "unavailable" ? null : true,
    checkedAt: "2026-10-31T10:00:00.000Z",
    diagnostics: state === "connected" ? [] : [{
      code: "TEST_STATE",
      severity: "error",
      title: "Test state",
      message: "OpenCode is not usable in this test.",
      repair: "Open setup.",
    }],
    discovery: state === "connected" || state === "degraded" ? discovery : null,
  };
}

function started(): Project {
  const project = createProject("/workspace");
  project.engine = {
    model: { providerID: "opencode", id: "flint-40b-free", variant: null },
    source: "user",
    updatedAt: null,
    legacyModel: null,
  };
  project.product = { status: "APPROVED", proposal: "Track found items.", openQuestions: [] };
  return refreshNextAction(project);
}

function approvedPlan(): Project {
  let project = started();
  for (const section of [...project.sections]) {
    project = reviseSection(project, section.id, `Approved ${section.id}.`);
    const current = project.sections.find((item) => item.id === section.id)!;
    project = approveSection(project, section.id, current.version, current.hash);
  }
  return project;
}

function asView(project: Project): WorkshopProject {
  return project as unknown as WorkshopProject;
}

test("selected tab parsing is case-insensitive and falls back to the active stage", () => {
  assert.equal(parseStageView("maker"), "MAKER");
  assert.equal(parseStageView("ARCHITECT"), "ARCHITECT");
  assert.equal(parseStageView(" witness "), "WITNESS");
  assert.equal(parseStageView("future"), null);
  assert.equal(parseStageView(""), null);
  assert.equal(parseStageView(null), null);
  assert.equal(resolveSelectedStage("witness", "ORACLE"), "WITNESS");
  assert.equal(resolveSelectedStage("bogus", "ARCHITECT"), "ARCHITECT");
});

test("view URLs preserve other query parameters and encode the selected stage", () => {
  assert.equal(viewHref("MAKER"), "?view=maker");
  assert.equal(viewHref("WITNESS", "?theme=dark&view=oracle"), "?theme=dark&view=witness");
  const href = viewHref("ARCHITECT", "?view=oracle");
  assert.equal(resolveSelectedStage(new URL(href, "http://localhost").searchParams.get("view"), "ORACLE"), "ARCHITECT");
});

test("completed, active, and future stages are distinct", () => {
  assert.equal(stageRelationship("ARCHITECT", "ORACLE"), "completed");
  assert.equal(stageRelationship("ARCHITECT", "ARCHITECT"), "active");
  assert.equal(stageRelationship("ARCHITECT", "MAKER"), "future");
  assert.equal(stageReached("MAKER", "ARCHITECT"), true);
  assert.equal(stageReached("MAKER", "WITNESS"), false);
  assert.equal(stageAriaLabel("MAKER", "future"), "Maker, future stage");
});

test("a future Maker or Witness tab is inspectable but read-only and cannot activate the stage", () => {
  const project = asView(createProject("/workspace"));
  for (const stage of ["MAKER", "WITNESS"] as const) {
    const view = buildStageView(project, connection(), stage);
    assert.equal(view.activeStage, "ORACLE");
    assert.equal(view.selectedStage, stage);
    assert.equal(view.relationship, "future");
    assert.equal(view.canMutate, false);
    assert.equal(view.isReadOnly, true);
    assert.match(view.notice ?? "", /does not approve|does not change/);
    assert.equal(view.currentRun, null);
    assert.ok(view.prerequisites.length > 0);
    assert.equal(view.prerequisites.every((prerequisite) => !prerequisite.met), true);
  }
});

test("the active stage is the only stage whose permitted actions are available", () => {
  const project = asView(started());
  const active = buildStageView(project, connection(), "ARCHITECT");
  assert.equal(active.relationship, "active");
  assert.equal(active.canMutate, true);
  assert.equal(active.isReadOnly, false);
  assert.equal(active.notice, null);

  const completed = buildStageView(project, connection(), "ORACLE");
  assert.equal(completed.relationship, "completed");
  assert.equal(completed.canMutate, false);
  assert.match(completed.notice ?? "", /reviewing the completed/);
});

test("progress counts stages and approved sections without inventing a percentage", () => {
  const project = asView(approvedPlan());
  assert.equal(progressLabel(project), "Witness active · 8 of 8 sections approved · 4 of 4 stages reached");
  const overview = buildProjectOverview(project, connection());
  assert.equal(overview.progress.stagesReached, 4);
  assert.equal(overview.progress.sectionsApproved, 8);
  assert.doesNotMatch(overview.progress.label, /%/);
});

test("section cards show ready, locked, blocked, stale, and approved states", () => {
  let project = started();
  let cards = buildSectionCards(asView(project));
  assert.equal(cards.find((card) => card.id === "control")?.state, "empty");
  assert.equal(cards.find((card) => card.id === "control")?.action.enabled, true);
  assert.equal(cards.find((card) => card.id === "architecture")?.state, "locked");
  assert.equal(cards.find((card) => card.id === "architecture")?.action.enabled, false);

  project = reviseSection(project, "control", "Vision text.");
  const control = project.sections.find((section) => section.id === "control")!;
  project = approveSection(project, "control", control.version, control.hash);
  cards = buildSectionCards(asView(project));
  assert.equal(cards.find((card) => card.id === "control")?.state, "approved");
  assert.equal(cards.find((card) => card.id === "architecture")?.state, "empty");

  project = reviseSection(project, "architecture", "Architecture text.");
  const architecture = project.sections.find((section) => section.id === "architecture")!;
  project = approveSection(project, "architecture", architecture.version, architecture.hash);
  cards = buildSectionCards(asView(project));
  assert.equal(cards.find((card) => card.id === "tools")?.state, "blocked");
  assert.equal(cards.find((card) => card.id === "tools")?.action.label, "Waiting for earlier sections");
});

test("a changed upstream section shows a stale reason without erasing unrelated approvals", () => {
  let project = approvedPlan();
  project = reviseSection(project, "tools", "Changed OpenCode setup.");
  const cards = buildSectionCards(asView(project));
  assert.equal(cards.find((card) => card.id === "experience")?.state, "approved");
  for (const id of ["readiness", "verification", "phases", "delivery"]) {
    const card = cards.find((entry) => entry.id === id)!;
    assert.equal(card.state, "stale");
    assert.match(card.staleReason ?? "", /changed/i);
  }
});

test("project overview exposes readiness, blockers, run state, connection, budget, tools, and demo status", () => {
  const project = started();
  const running: Project = structuredClone(project);
  running.operations.push({
    id: "run-1",
    kind: "maker",
    payloadHash: "hash",
    nativeSessionId: "ses_1",
    nativeMessageId: null,
    status: "RUNNING",
    result: "Editing files.",
    model: { providerID: "opencode", id: "flint-40b-free", variant: null },
    agent: "build",
    startedAt: "2026-10-31T10:00:00.000Z",
    finishedAt: null,
  });
  const overview = buildProjectOverview(asView(running), connection());
  assert.equal(overview.readiness.state, "in_progress");
  assert.equal(overview.currentRun?.isActive, true);
  assert.equal(overview.currentRun?.canCancel, true);
  assert.equal(overview.openCode.healthy, true);
  assert.equal(overview.budget.label, "Free model reported");
  assert.equal(overview.demo.label, "Not started");
  assert.ok(overview.blockers.some((blocker) => blocker.id === "section-experience"));
  assert.match(overview.nextAction, /Review|Draft/);
});

test("unresolved connection and run failures remain visible in the overview", () => {
  const project = started();
  const unknown: Project = structuredClone(project);
  unknown.operations.push({
    id: "run-unknown",
    kind: "maker",
    payloadHash: "hash",
    nativeSessionId: "ses_unknown",
    nativeMessageId: null,
    status: "UNKNOWN",
    result: "Native outcome is still unknown.",
    model: null,
    agent: null,
    startedAt: null,
    finishedAt: null,
  });
  const overview = buildProjectOverview(asView(unknown), connection("unavailable"));
  assert.equal(overview.readiness.state, "blocked");
  assert.equal(overview.currentRun?.canReconcile, true);
  assert.equal(overview.openCode.healthy, false);
  assert.ok(overview.blockers.some((blocker) => blocker.id === "connection"));
  assert.ok(overview.blockers.some((blocker) => blocker.id === "run-unknown-run-unknown"));
});

