import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";
import { renderToStaticMarkup } from "react-dom/server";
import { ProjectOverviewPanel, SectionCard, StagePreview } from "../src/web/App.tsx";
import { StageTabs } from "../src/web/stage-navigation.tsx";
import {
  buildProjectOverview,
  buildSectionCards,
  buildStageView,
} from "../src/web/workspace-view.ts";
import type { ConnectionStatus } from "../src/shared/opencode.ts";
import {
  createProject,
  refreshNextAction,
  type Project,
} from "../src/server/workflow/model.ts";
import { approveSection, reviseSection } from "../src/server/workflow/transitions.ts";
import type { WorkshopProject } from "../src/web/api.ts";

const connection: ConnectionStatus = {
  state: "connected",
  baseUrl: "http://127.0.0.1:4096",
  deploymentMode: "local",
  managed: false,
  auth: { mode: "none", username: "", hasPassword: false },
  serverVersion: "2.0.32",
  compatible: true,
  checkedAt: "2026-10-31T10:00:00.000Z",
  diagnostics: [],
  discovery: null,
};

function started(): Project {
  const project = createProject("/workspace");
  project.product = { status: "APPROVED", proposal: "Track found items.", openQuestions: [] };
  return refreshNextAction(project);
}

function asView(project: Project): WorkshopProject {
  return project as unknown as WorkshopProject;
}

test("stage navigation is a named landmark with link semantics, visible state, and one current tab", () => {
  const html = renderToStaticMarkup(
    <StageTabs activeStage="ARCHITECT" selectedStage="MAKER" />,
  );
  assert.match(html, /<nav[^>]*class="stage-strip"[^>]*aria-label="Spirit stages"/);
  assert.equal((html.match(/href="\?view=/g) ?? []).length, 4);
  assert.match(html, /aria-current="page"/);
  assert.match(html, /aria-label="Maker, future stage"/);
  assert.match(html, /aria-label="Architect, active stage"/);
  assert.match(html, /class="stage-badge">Active</);
  assert.doesNotMatch(html, /<button/);
});

test("the project overview exposes named sections and every required status area", () => {
  const project = asView(started());
  const overview = buildProjectOverview(project, connection);
  const html = renderToStaticMarkup(<ProjectOverviewPanel overview={overview} onOpenSetup={() => {}} />);
  assert.match(html, /id="project-overview"/);
  assert.match(html, /aria-labelledby="overview-heading"/);
  assert.match(html, /<h2 id="overview-heading">Project overview<\/h2>/);
  assert.match(html, /Active blockers/);
  assert.match(html, /Current run/);
  assert.match(html, /OpenCode state/);
  assert.match(html, /Budget &amp; tools/);
  assert.match(html, /Demo status/);
  assert.match(html, /Next action:/);
});

test("section cards expose summary, dependencies, update time, approval/evidence links, and a disabled lock", () => {
  let project = started();
  project = reviseSection(project, "control", "A clear vision and success measure.");
  const control = project.sections.find((section) => section.id === "control")!;
  project = approveSection(project, "control", control.version, control.hash);
  const cards = buildSectionCards(asView(project));
  const approved = cards.find((card) => card.id === "control")!;
  const locked = cards.find((card) => card.id === "verification")!;

  const approvedHtml = renderToStaticMarkup(
    <SectionCard section={approved} evidenceCount={0} onNavigate={() => {}} />,
  );
  assert.match(approvedHtml, /aria-labelledby="section-control-title"/);
  assert.match(approvedHtml, /Dependencies/);
  assert.match(approvedHtml, /Last update/);
  assert.match(approvedHtml, /id="section-control-approval"/);
  assert.match(approvedHtml, /id="section-control-evidence"/);
  assert.match(approvedHtml, /href="#evidence"/);

  const lockedHtml = renderToStaticMarkup(
    <SectionCard section={locked} evidenceCount={0} onNavigate={() => {}} />,
  );
  assert.match(lockedHtml, /aria-disabled="true"/);
  assert.doesNotMatch(lockedHtml, /<button/);
});

test("a future-stage preview is read-only and cannot render a mutation control", () => {
  const project = asView(createProject("/workspace"));
  const view = buildStageView(project, connection, "WITNESS");
  const html = renderToStaticMarkup(<StagePreview view={view} />);
  assert.match(html, /role="note"/);
  assert.match(html, /Viewing is not approval|does not approve/);
  assert.doesNotMatch(html, /<button/);
  assert.doesNotMatch(html, /<textarea/);
});

test("responsive and reduced-motion contracts are present", async () => {
  const css = await readFile(new URL("../src/web/styles.css", import.meta.url), "utf8");
  assert.match(css, /@media \(max-width: 620px\)/);
  assert.match(css, /@media \(max-width: 959px\)/);
  assert.match(css, /overflow-x: auto/);
  assert.match(css, /prefers-reduced-motion: reduce/);
  assert.match(css, /\.frame \.document/);
  assert.match(css, /overflow-wrap: anywhere/);
});

