const tab = (await tools.browser.tabs.list()).tabs[0];
await tools.browser.navigate({ tabID: tab.id, url: "http://127.0.0.1:4210/?view=architect" });
await tools.browser.wait({ tabID: tab.id, condition: "text", text: "Project overview", timeout: 10000 }).catch(() => null);
const result = await tools.browser.evaluate({ tabID: tab.id, script: `(() => {
  const ids = [...document.querySelectorAll('[id]')].map(el => el.id);
  const duplicates = ids.filter((id, index) => ids.indexOf(id) !== index);
  return {
    url: location.href,
    stage: document.querySelector('.active-badge')?.textContent,
    currentSection: document.querySelector('.section-card[aria-current="step"] h3')?.textContent,
    duplicateIds: [...new Set(duplicates)],
    hasDocumentTarget: Boolean(document.querySelector('#section-tools-document')),
    textareas: document.querySelectorAll('textarea').length,
    buttons: [...document.querySelectorAll('.document button, .document a.action')].map(el => el.textContent.trim()),
    headingFocusable: document.querySelector('#stage-title')?.getAttribute('tabindex'),
    overflow: [...document.querySelectorAll('*')].filter(el => el.scrollWidth > el.clientWidth + 2 && getComputedStyle(el).overflowX === 'visible').length
  };
})()` });
return result;

